// ---------------------------------------------------------------------------
// Data file format, described for other implementations in
// docs/apostille/CONFORMANCE.md. encoding/json emits members in struct field
// order, so that order is part of the generated bytes.
// ---------------------------------------------------------------------------

const conformanceProtocol = Protocol
const conformanceFormat = 1
const conformanceNotice = "Synthetic public test seeds. Never trust these keys. Inputs are exact bytes (unpadded base64url). Only 'expect' is normative; 'reason' is informative."

type inputGen struct {
	RepeatB64 string `json:"repeat_b64"`
	Count     int    `json:"count"`
}

type bundleOptions struct {
	Issuer string   `json:"issuer,omitempty"`
	KeyIDs []string `json:"key_ids,omitempty"`
	At     string   `json:"at,omitempty"`
}

// verificationExpect mirrors apostille/types.go:109-127's Verification JSON
// tags, minus "statement" (not part of the conformance contract).
type verificationExpect struct {
	Protocol            string `json:"protocol"`
	ArtifactIntegrity   string `json:"artifact_integrity"`
	IssuerTrust         string `json:"issuer_trust"`
	CertificateScope    string `json:"certificate_scope"`
	AgentBinding        string `json:"agent_binding"`
	OrganizationBinding string `json:"organization_binding"`
	AuthorizationPolicy string `json:"authorization_policy"`
	Freshness           string `json:"freshness"`
	TimeBasis           string `json:"time_basis"`
	ContentTruth        string `json:"content_truth"`
	ProviderEvidence    string `json:"provider_evidence"`
	LogInclusion        string `json:"log_inclusion"`
	Anchor              string `json:"anchor"`
	Issuer              string `json:"issuer"`
	IssuerKeyID         string `json:"issuer_key_id"`
	CertificateID       string `json:"certificate_id"`
}

type bundleExpect struct {
	Result        string              `json:"result"`
	Verification  *verificationExpect `json:"verification,omitempty"`
	ArtifactMatch *bool               `json:"artifact_match,omitempty"`
}

type bundleCase struct {
	Name        string        `json:"name"`
	Reason      string        `json:"reason"`
	InputB64    *string       `json:"input_b64,omitempty"`
	InputGen    *inputGen     `json:"input_gen,omitempty"`
	Options     bundleOptions `json:"options"`
	ArtifactB64 *string       `json:"artifact_b64,omitempty"`
	Expect      bundleExpect  `json:"expect"`
}

type strictJSONCase struct {
	Name         string    `json:"name"`
	Reason       string    `json:"reason"`
	InputB64     *string   `json:"input_b64,omitempty"`
	InputGen     *inputGen `json:"input_gen,omitempty"`
	Expect       string    `json:"expect"`
	CanonicalB64 *string   `json:"canonical_b64,omitempty"`
}

type issuerConformanceCase struct {
	Value  string `json:"value"`
	Expect string `json:"expect"`
}

type conformanceFile struct {
	Protocol        string                  `json:"protocol"`
	Format          int                     `json:"format"`
	Notice          string                  `json:"notice"`
	BundleCases     []bundleCase            `json:"bundle_cases"`
	StrictJSONCases []strictJSONCase        `json:"strict_json_cases"`
	IssuerCases     []issuerConformanceCase `json:"issuer_cases"`
}

// ---------------------------------------------------------------------------
// Shared generator helpers (never written to the data file).
// ---------------------------------------------------------------------------

const secondAgentID = "dddddddd-dddd-4ddd-8ddd-dddddddddddd"

func strPtr(s string) *string { return &s }

// fixedBundle returns a fully delegated bundle identical to the one written
// to testdata/apostille/core-0.1.json: fixture(t) followed by the same
// certificate-id fix-up and re-sign TestWriteInteroperabilityFixture performs
// (apostille_test.go:228-232).
func fixedBundle(t *testing.T) (Bundle, *Signer, *Signer, *Signer) {
	t.Helper()
	b, admin, agent, issuer := fixture(t)
	var c Certificate
	if err := DecodePayload(*b.Certificate, KindCertificate, &c); err != nil {
		t.Fatal(err)
	}
	c.CertificateID = "cccccccc-cccc-4ccc-8ccc-cccccccccccc"
	ce := mustSign(t, issuer, KindCertificate, c)
	b.Certificate = &ce
	return b, admin, agent, issuer
}

// producerOnlyStatement is the exact Statement TestSelfIssuedCoreWithoutRegistration
// (apostille_test.go:197-205) builds for signer 4, factored out so mutation
// helpers can start from the identical struct.
func producerOnlyStatement(s *Signer) Statement {
	return Statement{Header: NewHeader(KindStatement, KeyIdentity(s.KeyID()), s, fixedNow), AgentID: agentID, ArtifactSHA256: Hash(nil), ArtifactSize: "0", ArtifactMediaType: "application/octet-stream", Nonce: nonceID}
}

// producerOnly returns a key-profile bundle: single statement envelope, no
// delegation/acceptance/certificate, signed by testSigner(t,4).
func producerOnly(t *testing.T) (Bundle, *Signer) {
	t.Helper()
	s := testSigner(t, 4)
	se := mustSign(t, s, KindStatement, producerOnlyStatement(s))
	return Bundle{Protocol: Protocol, Statement: se}, s
}

// signRaw builds an Envelope over arbitrary payload bytes with a real
// signature and no payload validation, asserting the signature verifies.
func signRaw(t testing.TB, s *Signer, kind string, payload []byte) Envelope {
	t.Helper()
	input := signingInput(kind, payload)
	sig := ed25519.Sign(s.key, input)
	if !ed25519.Verify(s.key.Public().(ed25519.PublicKey), input, sig) {
		t.Fatal("signRaw: produced signature does not verify")
	}
	return Envelope{
		Protocol:      Protocol,
		Kind:          kind,
		Payload:       rawURL.EncodeToString(payload),
		PayloadSHA256: Hash(payload),
		Signature: Signature{
			Algorithm: Algorithm,
			KeyID:     s.KeyID(),
			PublicKey: s.PublicKey(),
			Value:     rawURL.EncodeToString(sig),
		},
	}
}

// certFor builds the Certificate struct the way Issue does (verify.go:263-267)
// but with a fixed id and times, without calling Issue/NewID.
func certFor(t *testing.T, b Bundle, issuer *Signer, issuerID string, issuedAt, expiresAt time.Time, id string) Certificate {
	t.Helper()
	var s Statement
	if err := DecodePayload(b.Statement, KindStatement, &s); err != nil {
		t.Fatal(err)
	}
	sh, err := EnvelopeDigest(b.Statement)
	if err != nil {
		t.Fatal(err)
	}
	binding := "not_provided"
	if b.Delegation != nil {
		binding = "admin_key_delegation"
	}
	return Certificate{
		Header:              NewHeader(KindCertificate, issuerID, issuer, issuedAt),
		CertificateID:       id,
		StatementSHA256:     sh,
		DelegationSHA256:    s.DelegationSHA256,
		SourceKeyID:         s.IssuerKeyID,
		ExpiresAt:           expiresAt.UTC().Format(TimestampLayout),
		SignatureCheck:      "valid",
		AgentBinding:        binding,
		OrganizationBinding: "unproven",
		ContentTruth:        "not_established",
	}
}

// mutateJSON marshals b, decodes it into a generic map, lets f mutate that
// map, and re-marshals. Used for structural bundle mutations where field
// presence/absence/naming matters more than a typed Go value.
func mutateJSON(t *testing.T, b Bundle, f func(m map[string]any)) []byte {
	t.Helper()
	raw, err := json.Marshal(b)
	if err != nil {
		t.Fatal(err)
	}
	var m map[string]any
	if err := json.Unmarshal(raw, &m); err != nil {
		t.Fatal(err)
	}
	f(m)
	out, err := json.Marshal(m)
	if err != nil {
		t.Fatal(err)
	}
	return out
}

// rawJSON is a plain json.Marshal that t.Fatals on error.
func rawJSON(t *testing.T, v any) []byte {
	t.Helper()
	raw, err := json.Marshal(v)
	if err != nil {
		t.Fatal(err)
	}
	return raw
}

// replaceOnce performs exactly one substring replacement on canonical payload
// bytes and fails the test if the replacement did not change anything.
func replaceOnce(t *testing.T, raw []byte, old, new string) []byte {
	t.Helper()
	out := bytes.Replace(raw, []byte(old), []byte(new), 1)
	if bytes.Equal(out, raw) {
		t.Fatalf("replacement %q -> %q did not change payload %s", old, new, raw)
	}
	return out
}

// pin returns the fixed trust policy used by most accept/reject cases:
// {issuer: exampleIssuer, key_ids: [issuer.KeyID()], at: 2026-09-13T01:00:00Z}.
func pin(issuer *Signer) VerifyOptions {
	return VerifyOptions{ExpectedIssuer: exampleIssuer, TrustedKeyIDs: []string{issuer.KeyID()}, Now: fixedNow.Add(time.Hour)}
}

func toOptions(opts VerifyOptions) bundleOptions {
	o := bundleOptions{Issuer: opts.ExpectedIssuer, KeyIDs: opts.TrustedKeyIDs}
	if !opts.Now.IsZero() {
		o.At = opts.Now.UTC().Format(TimestampLayout)
	}
	return o
}

func expectFromVerification(v Verification) *verificationExpect {
	return &verificationExpect{
		Protocol:            v.Protocol,
		ArtifactIntegrity:   v.ArtifactIntegrity,
		IssuerTrust:         v.IssuerTrust,
		CertificateScope:    v.CertificateScope,
		AgentBinding:        v.AgentBinding,
		OrganizationBinding: v.OrganizationBinding,
		AuthorizationPolicy: v.AuthorizationPolicy,
		Freshness:           v.Freshness,
		TimeBasis:           v.TimeBasis,
		ContentTruth:        v.ContentTruth,
		ProviderEvidence:    v.ProviderEvidence,
		LogInclusion:        v.LogInclusion,
		Anchor:              v.Anchor,
		Issuer:              v.Issuer,
		IssuerKeyID:         v.IssuerKeyID,
		CertificateID:       v.CertificateID,
	}
}

// acceptCase runs raw/opts through Verify, requires acceptance, and builds
// the bundleCase entry with expect.verification derived directly from the
// actual result (so the file can never drift from Go's real behaviour). It
// returns the actual Verification so callers can assert "key expectations"
// from the spec's case tables.
func acceptCase(t *testing.T, name, reason string, raw []byte, opts VerifyOptions) (bundleCase, Verification) {
	t.Helper()
	v, err := Verify(raw, opts)
	if err != nil {
		t.Fatalf("%s: expected accept, got error: %v", name, err)
	}
	// core-0.1.md "Result semantics": these dimensions are fixed in 0.1, so
	// they are checked against the specification rather than copied from Go.
	if v.Protocol != Protocol || v.ArtifactIntegrity != "valid" || v.OrganizationBinding != "unproven" || v.ContentTruth != "not_established" || v.ProviderEvidence != "not_provided" || v.LogInclusion != "not_registered" || v.Anchor != "not_requested" {
		t.Fatalf("%s: fixed 0.1 result dimensions changed: %+v", name, v)
	}
	bc := bundleCase{
		Name:     name,
		Reason:   reason,
		InputB64: strPtr(rawURL.EncodeToString(raw)),
		Options:  toOptions(opts),
		Expect:   bundleExpect{Result: "accept", Verification: expectFromVerification(v)},
	}
	return bc, v
}

// withArtifact attaches an artifact comparison to an already-built accept
// case, asserting the actual match result equals wantMatch.
func withArtifact(t *testing.T, name string, bc bundleCase, v Verification, artifact []byte, wantMatch bool) bundleCase {
	t.Helper()
	got := VerifyArtifact(v, artifact)
	if got != wantMatch {
		t.Fatalf("%s: artifact_match = %v, want %v", name, got, wantMatch)
	}
	bc.ArtifactB64 = strPtr(rawURL.EncodeToString(artifact))
	bc.Expect.ArtifactMatch = &got
	return bc
}

// rejectCase runs raw/opts through Verify, requires rejection with an error
// containing wantErr, and builds the bundleCase entry.
func rejectCase(t *testing.T, name, reason string, raw []byte, opts VerifyOptions, wantErr string) bundleCase {
	t.Helper()
	_, err := Verify(raw, opts)
	if err == nil {
		t.Fatalf("%s: expected rejection, got accept", name)
	}
	if !strings.Contains(err.Error(), wantErr) {
		t.Fatalf("%s: rejected for wrong reason: got %q, want substring %q", name, err.Error(), wantErr)
	}
	return bundleCase{
		Name:     name,
		Reason:   reason,
		InputB64: strPtr(rawURL.EncodeToString(raw)),
		Options:  toOptions(opts),
		Expect:   bundleExpect{Result: "reject"},
	}
}

// rejectGenCase is rejectCase's input_gen counterpart: decoded is what the
// generator actually feeds to Verify for self-checking, gen is what gets
// written to the file.
func rejectGenCase(t *testing.T, name, reason string, gen inputGen, decoded []byte, opts VerifyOptions, wantErr string) bundleCase {
	t.Helper()
	_, err := Verify(decoded, opts)
	if err == nil {
		t.Fatalf("%s: expected rejection, got accept", name)
	}
	if !strings.Contains(err.Error(), wantErr) {
		t.Fatalf("%s: rejected for wrong reason: got %q, want substring %q", name, err.Error(), wantErr)
	}
	return bundleCase{
		Name:     name,
		Reason:   reason,
		InputGen: &gen,
		Options:  toOptions(opts),
		Expect:   bundleExpect{Result: "reject"},
	}
}

func requireNoErr(t *testing.T, name string, err error) {
	t.Helper()
	if err != nil {
		t.Fatalf("%s: %v", name, err)
	}
}

// ---------------------------------------------------------------------------
// bundle_cases — accept
// ---------------------------------------------------------------------------

func bundleAcceptCases(t *testing.T) []bundleCase {
	t.Helper()
	var out []bundleCase

	b, _, _, issuer := fixedBundle(t)
	raw := rawJSON(t, b)
	// Before mutating anything derived from this bundle, confirm the
	// unmutated baseline verifies.
	if _, err := Verify(raw, VerifyOptions{}); err != nil {
		t.Fatalf("fixedBundle: unmutated bundle failed to verify: %v", err)
	}

	pinOpts := pin(issuer)
	name := "accept/pinned-issuer-valid-time"
	bc, v := acceptCase(t, name, "A fully delegated bundle, pinned to its issuer's exact issuer+key, verifies with a matching artifact.", raw, pinOpts)
	if v.IssuerTrust != "accepted_by_policy" || v.Freshness != "valid_at_evaluation_time" || v.CertificateScope != "origin_signature_checked" || v.AgentBinding != "admin_key_delegation" || v.AuthorizationPolicy != "current_revocation_unknown" || v.TimeBasis != "issuer_claimed_check_time" {
		t.Fatalf("%s: unexpected verification: %+v", name, v)
	}
	out = append(out, withArtifact(t, name, bc, v, []byte("hello\n"), true))

	name = "accept/artifact-content-changed"
	bc, v = acceptCase(t, name, "A same-length substituted artifact still fails artifact_match even though the bundle itself verifies.", raw, pinOpts)
	out = append(out, withArtifact(t, name, bc, v, []byte("hello!"), false))

	name = "accept/artifact-length-changed"
	bc, v = acceptCase(t, name, "A different-length substituted artifact fails artifact_match.", raw, pinOpts)
	out = append(out, withArtifact(t, name, bc, v, []byte("changed"), false))

	name = "accept/no-policy"
	bc, v = acceptCase(t, name, "With no supplied trust policy, issuer_trust and freshness are unknown rather than accepted or untrusted.", raw, VerifyOptions{})
	if v.IssuerTrust != "unknown" || v.Freshness != "unknown" {
		t.Fatalf("%s: unexpected verification: %+v", name, v)
	}
	out = append(out, bc)

	name = "accept/issuer-only-policy"
	bc, v = acceptCase(t, name, "An issuer alone, without a trusted key, is not enough to accept by policy.", raw, VerifyOptions{ExpectedIssuer: exampleIssuer})
	if v.IssuerTrust != "untrusted" {
		t.Fatalf("%s: unexpected verification: %+v", name, v)
	}
	out = append(out, bc)

	name = "accept/key-only-policy"
	bc, v = acceptCase(t, name, "A trusted key alone, without an expected issuer, is not enough to accept by policy.", raw, VerifyOptions{TrustedKeyIDs: []string{issuer.KeyID()}})
	if v.IssuerTrust != "untrusted" {
		t.Fatalf("%s: unexpected verification: %+v", name, v)
	}
	out = append(out, bc)

	name = "accept/wrong-issuer-policy"
	bc, v = acceptCase(t, name, "The right key but a different expected issuer does not yield accepted_by_policy.", raw, VerifyOptions{ExpectedIssuer: "https://another.example/apostille", TrustedKeyIDs: []string{issuer.KeyID()}})
	if v.IssuerTrust != "untrusted" {
		t.Fatalf("%s: unexpected verification: %+v", name, v)
	}
	out = append(out, bc)

	name = "accept/wrong-key-policy"
	bc, v = acceptCase(t, name, "The right issuer but a wrong trusted key does not yield accepted_by_policy.", raw, VerifyOptions{ExpectedIssuer: exampleIssuer, TrustedKeyIDs: []string{"sha256:" + strings.Repeat("0", 64)}})
	if v.IssuerTrust != "untrusted" {
		t.Fatalf("%s: unexpected verification: %+v", name, v)
	}
	out = append(out, bc)

	name = "accept/expired-at-evaluation"
	bc, v = acceptCase(t, name, "Evaluating long after certificate expiry still verifies the signature; freshness reports expired.", raw, VerifyOptions{ExpectedIssuer: exampleIssuer, TrustedKeyIDs: []string{issuer.KeyID()}, Now: time.Date(2030, 1, 1, 0, 0, 0, 0, time.UTC)})
	if v.Freshness != "expired" || v.ArtifactIntegrity != "valid" {
		t.Fatalf("%s: unexpected verification: %+v", name, v)
	}
	out = append(out, bc)

	name = "accept/not-yet-valid-at-evaluation"
	bc, v = acceptCase(t, name, "Evaluating before the certificate's issued_at reports not_yet_valid.", raw, VerifyOptions{ExpectedIssuer: exampleIssuer, TrustedKeyIDs: []string{issuer.KeyID()}, Now: fixedNow})
	if v.Freshness != "not_yet_valid" {
		t.Fatalf("%s: unexpected verification: %+v", name, v)
	}
	out = append(out, bc)

	var cert Certificate
	requireNoErr(t, name, DecodePayload(*b.Certificate, KindCertificate, &cert))
	expiresAt, err := Timestamp(cert.ExpiresAt)
	requireNoErr(t, name, err)
	issuedAt, err := Timestamp(cert.IssuedAt)
	requireNoErr(t, name, err)

	name = "accept/expiry-boundary-is-exclusive"
	bc, v = acceptCase(t, name, "Evaluating exactly at the certificate's expires_at reports expired: the interval is half-open.", raw, VerifyOptions{ExpectedIssuer: exampleIssuer, TrustedKeyIDs: []string{issuer.KeyID()}, Now: expiresAt})
	if v.Freshness != "expired" {
		t.Fatalf("%s: unexpected verification: %+v", name, v)
	}
	out = append(out, bc)

	name = "accept/issue-boundary-is-inclusive"
	bc, v = acceptCase(t, name, "Evaluating exactly at the certificate's issued_at reports valid_at_evaluation_time: the interval is half-open.", raw, VerifyOptions{ExpectedIssuer: exampleIssuer, TrustedKeyIDs: []string{issuer.KeyID()}, Now: issuedAt})
	if v.Freshness != "valid_at_evaluation_time" {
		t.Fatalf("%s: unexpected verification: %+v", name, v)
	}
	out = append(out, bc)

	name = "accept/producer-only-delegated"
	delegatedNoCert := b
	delegatedNoCert.Certificate = nil
	bc, v = acceptCase(t, name, "A delegated bundle without a certificate is producer_only: no issuer trust or freshness is established even though a delegation exists.", rawJSON(t, delegatedNoCert), pinOpts)
	if v.CertificateScope != "producer_only" || v.IssuerTrust != "unknown" || v.AuthorizationPolicy != "unknown" || v.TimeBasis != "producer_claimed" || v.Freshness != "unknown" || v.AgentBinding != "admin_key_delegation" || v.CertificateID != "" {
		t.Fatalf("%s: unexpected verification: %+v", name, v)
	}
	out = append(out, bc)

	pOnly, signer4 := producerOnly(t)
	pRaw := rawJSON(t, pOnly)
	name = "accept/producer-only-key-profile"
	bc, v = acceptCase(t, name, "The bare key profile (no delegation, no certificate) verifies as producer_only with no agent binding, and an empty artifact still matches.", pRaw, VerifyOptions{})
	if v.AgentBinding != "not_provided" || v.CertificateScope != "producer_only" {
		t.Fatalf("%s: unexpected verification: %+v", name, v)
	}
	out = append(out, withArtifact(t, name, bc, v, []byte{}, true))

	name = "accept/self-issued-urn-issuer"
	selfIssued := pOnly
	selfCert := certFor(t, pOnly, signer4, "urn:example:private-issuer", fixedNow, fixedNow.Add(24*time.Hour), "eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee")
	ce := mustSign(t, signer4, KindCertificate, selfCert)
	selfIssued.Certificate = &ce
	bc, v = acceptCase(t, name, "A single key can self-issue its own certificate without any registration profile.", rawJSON(t, selfIssued), VerifyOptions{ExpectedIssuer: "urn:example:private-issuer", TrustedKeyIDs: []string{signer4.KeyID()}, Now: fixedNow})
	if v.IssuerTrust != "accepted_by_policy" || v.AgentBinding != "not_provided" {
		t.Fatalf("%s: unexpected verification: %+v", name, v)
	}
	out = append(out, bc)

	name = "accept/outer-whitespace-and-reordered-members"
	reordered := reorderedWhitespaceBundle(t, b)
	if bytes.Equal(reordered, raw) {
		t.Fatalf("%s: reordered bytes are identical to canonical bytes", name)
	}
	bc, v = acceptCase(t, name, "Outer bundle/envelope member order and insignificant whitespace do not affect verification.", reordered, pinOpts)
	if v.IssuerTrust != "accepted_by_policy" || v.Freshness != "valid_at_evaluation_time" {
		t.Fatalf("%s: unexpected verification: %+v", name, v)
	}
	out = append(out, bc)

	return out
}

// reorderedWhitespaceBundle hand-assembles the outer bundle JSON with members
// in reverse order (certificate, acceptance, delegation, statement, protocol)
// and each envelope's members also reordered, with extra insignificant
// whitespace between tokens. Field values come from json.Marshal of each
// individual field, so their content is exact; only the outer arrangement is
// hand-built.
func reorderedWhitespaceBundle(t *testing.T, b Bundle) []byte {
	t.Helper()
	env := func(e Envelope) string {
		return fmt.Sprintf("{\n\t\"signature\" : {\"value\":%s,\t\"public_key\":%s,\"key_id\":%s,\"algorithm\":%s},\n\"payload_sha256\":%s,\n\"payload\":%s,\n\"kind\":%s,\n\"protocol\":%s\n}",
			string(rawJSON(t, e.Signature.Value)), string(rawJSON(t, e.Signature.PublicKey)), string(rawJSON(t, e.Signature.KeyID)), string(rawJSON(t, e.Signature.Algorithm)),
			string(rawJSON(t, e.PayloadSHA256)), string(rawJSON(t, e.Payload)), string(rawJSON(t, e.Kind)), string(rawJSON(t, e.Protocol)))
	}
	var buf bytes.Buffer
	buf.WriteString(" {\n")
	buf.WriteString("\"certificate\":")
	buf.WriteString(env(*b.Certificate))
	buf.WriteString(" ,\n\"acceptance\" :\t")
	buf.WriteString(env(*b.Acceptance))
	buf.WriteString(",\n\"delegation\":  ")
	buf.WriteString(env(*b.Delegation))
	buf.WriteString(",\n\t\"statement\":")
	buf.WriteString(env(b.Statement))
	buf.WriteString(",\n \"protocol\" :  ")
	buf.Write(rawJSON(t, b.Protocol))
	buf.WriteString("\n}\n ")
	return buf.Bytes()
}

// ---------------------------------------------------------------------------
// bundle_cases — reject: tampering (fixedBundle, pin)
// ---------------------------------------------------------------------------

// cloneBundle deep-copies a Bundle's pointer-typed envelope fields so callers
// can mutate the copy without aliasing the original.
func cloneBundle(b Bundle) Bundle {
	out := b
	if b.Delegation != nil {
		d := *b.Delegation
		out.Delegation = &d
	}
	if b.Acceptance != nil {
		a := *b.Acceptance
		out.Acceptance = &a
	}
	if b.Certificate != nil {
		c := *b.Certificate
		out.Certificate = &c
	}
	return out
}

// standardAlphabetCase finds the first envelope string field (payload,
// signature.value or signature.public_key, in statement/delegation/
// acceptance/certificate order) containing '-' or '_', flips it to the
// standard (non-URL-safe) base64 alphabet, and derives wantErr from which
// field it hit.
func standardAlphabetCase(t *testing.T, b Bundle, opts VerifyOptions) bundleCase {
	t.Helper()
	var label string
	raw := mutateJSON(t, b, func(m map[string]any) {
		flip := strings.NewReplacer("-", "+", "_", "/")
		for _, name := range []string{"statement", "delegation", "acceptance", "certificate"} {
			env, ok := m[name].(map[string]any)
			if !ok {
				continue
			}
			if s, ok := env["payload"].(string); ok && strings.ContainsAny(s, "-_") {
				env["payload"] = flip.Replace(s)
				label = name + ".payload"
				return
			}
			sig, ok := env["signature"].(map[string]any)
			if !ok {
				continue
			}
			if s, ok := sig["value"].(string); ok && strings.ContainsAny(s, "-_") {
				sig["value"] = flip.Replace(s)
				label = name + ".signature.value"
				return
			}
			if s, ok := sig["public_key"].(string); ok && strings.ContainsAny(s, "-_") {
				sig["public_key"] = flip.Replace(s)
				label = name + ".signature.public_key"
				return
			}
		}
	})
	if label == "" {
		t.Fatal("reject/standard-base64-alphabet: no envelope field containing - or _ was found")
	}
	var wantErr string
	switch {
	case strings.HasSuffix(label, ".payload"):
		wantErr = "invalid payload encoding or size"
	case strings.HasSuffix(label, ".signature.value"):
		wantErr = "invalid source signature"
	case strings.HasSuffix(label, ".signature.public_key"):
		wantErr = "key fingerprint mismatch"
	}
	return rejectCase(t, "reject/standard-base64-alphabet",
		fmt.Sprintf("Standard base64 characters (+/) substituted into %s, where only unpadded base64url (-_) is valid, are rejected as invalid encoding rather than silently normalized.", label),
		raw, opts, wantErr)
}

func bundleTamperingCases(t *testing.T) []bundleCase {
	t.Helper()
	b, _, _, issuer := fixedBundle(t)
	opts := pin(issuer)
	var out []bundleCase

	out = append(out, rejectCase(t, "reject/payload-digest-zeroed",
		"A statement envelope whose payload_sha256 no longer matches its actual payload is rejected before any signature check.",
		mutateJSON(t, b, func(m map[string]any) {
			m["statement"].(map[string]any)["payload_sha256"] = strings.Repeat("0", 64)
		}), opts, "payload digest mismatch"))

	out = append(out, rejectCase(t, "reject/payload-replaced",
		"Swapping the statement payload without updating its digest is caught by the digest check.",
		mutateJSON(t, b, func(m map[string]any) {
			m["statement"].(map[string]any)["payload"] = rawURL.EncodeToString([]byte(`{}`))
		}), opts, "payload digest mismatch"))

	out = append(out, rejectCase(t, "reject/payload-replaced-consistent-digest",
		"Swapping the statement payload and updating its digest to match still fails: the original signature no longer covers the new bytes.",
		mutateJSON(t, b, func(m map[string]any) {
			newPayload := []byte(`{}`)
			st := m["statement"].(map[string]any)
			st["payload"] = rawURL.EncodeToString(newPayload)
			st["payload_sha256"] = Hash(newPayload)
		}), opts, "invalid source signature"))

	out = append(out, rejectCase(t, "reject/signature-bit-flipped",
		"Flipping one bit of the certificate signature invalidates it.",
		mutateJSON(t, b, func(m map[string]any) {
			cert := m["certificate"].(map[string]any)
			sig := cert["signature"].(map[string]any)
			raw, err := rawURL.DecodeString(sig["value"].(string))
			if err != nil {
				t.Fatal(err)
			}
			raw[0] ^= 1
			sig["value"] = rawURL.EncodeToString(raw)
		}), opts, "invalid source signature"))

	out = append(out, rejectCase(t, "reject/signature-padded",
		"A padded ('=') certificate signature is not valid unpadded base64url and fails to decode.",
		mutateJSON(t, b, func(m map[string]any) {
			sig := m["certificate"].(map[string]any)["signature"].(map[string]any)
			sig["value"] = sig["value"].(string) + "="
		}), opts, "invalid source signature"))

	out = append(out, rejectCase(t, "reject/signature-truncated",
		"Dropping the last two characters of the certificate signature yields the wrong decoded length.",
		mutateJSON(t, b, func(m map[string]any) {
			sig := m["certificate"].(map[string]any)["signature"].(map[string]any)
			v := sig["value"].(string)
			sig["value"] = v[:len(v)-2]
		}), opts, "invalid source signature"))

	out = append(out, standardAlphabetCase(t, b, opts))

	out = append(out, rejectCase(t, "reject/public-key-swapped",
		"Substituting the certificate signature's public key with the statement's agent key no longer fingerprints to the declared issuer key_id.",
		mutateJSON(t, b, func(m map[string]any) {
			cert := m["certificate"].(map[string]any)["signature"].(map[string]any)
			st := m["statement"].(map[string]any)["signature"].(map[string]any)
			cert["public_key"] = st["public_key"]
		}), opts, "key fingerprint mismatch"))

	out = append(out, rejectCase(t, "reject/key-id-swapped",
		"Substituting the certificate signature's key_id with the statement's agent key_id no longer matches the certificate's real public key.",
		mutateJSON(t, b, func(m map[string]any) {
			cert := m["certificate"].(map[string]any)["signature"].(map[string]any)
			st := m["statement"].(map[string]any)["signature"].(map[string]any)
			cert["key_id"] = st["key_id"]
		}), opts, "key fingerprint mismatch"))

	return out
}

