// ---------------------------------------------------------------------------
// bundle_cases — reject: signed-payload encoding (producerOnly base,
// statement rebuilt with signRaw, all validly signed)
// ---------------------------------------------------------------------------

// reorderProtocolFirst moves the trailing "protocol" member of a canonical
// Statement payload to the front, producing valid but non-canonically
// ordered JSON with the same members.
func reorderProtocolFirst(t *testing.T, p []byte) []byte {
	t.Helper()
	trailing := []byte(`,"protocol":"` + Protocol + `"}`)
	if !bytes.Contains(p, trailing) {
		t.Fatal("reorderProtocolFirst: expected trailing protocol member not found")
	}
	out := bytes.Replace(p, trailing, []byte("}"), 1)
	out = bytes.Replace(out, []byte("{"), []byte(`{"protocol":"`+Protocol+`",`), 1)
	if bytes.Equal(out, p) {
		t.Fatal("reorderProtocolFirst: did not change payload")
	}
	return out
}

func bundlePayloadEncodingCases(t *testing.T) []bundleCase {
	t.Helper()
	b, s := producerOnly(t)
	if _, err := Verify(rawJSON(t, b), VerifyOptions{}); err != nil {
		t.Fatalf("producerOnly: unmutated bundle failed to verify: %v", err)
	}
	stmt := producerOnlyStatement(s)
	p, err := Canonical(stmt)
	requireNoErr(t, "bundlePayloadEncodingCases", err)

	build := func(name, reason string, payload []byte, wantErr string) bundleCase {
		bad := b
		bad.Statement = signRaw(t, s, KindStatement, payload)
		return rejectCase(t, name, reason, rawJSON(t, bad), VerifyOptions{}, wantErr)
	}

	var out []bundleCase

	out = append(out, build("reject/payload-utf8-bom-validly-signed",
		"A UTF-8 BOM before an otherwise-canonical, validly signed payload is not insignificant JSON whitespace and is rejected as malformed.",
		append([]byte("\xEF\xBB\xBF"), p...), "invalid JSON"))

	out = append(out, build("reject/payload-leading-space-validly-signed",
		"A leading space before an otherwise-canonical, validly signed payload is legal JSON whitespace but is not canonical.",
		append([]byte(" "), p...), "payload is not canonical JSON"))

	out = append(out, build("reject/payload-trailing-newline-validly-signed",
		"A trailing newline after an otherwise-canonical, validly signed payload is legal JSON whitespace but is not canonical.",
		append(append([]byte{}, p...), '\n'), "payload is not canonical JSON"))

	out = append(out, build("reject/payload-members-reordered-validly-signed",
		"A validly signed payload with the same members in non-canonical order re-canonicalizes to different bytes and is rejected.",
		reorderProtocolFirst(t, p), "payload is not canonical JSON"))

	out = append(out, build("reject/payload-escaped-solidus-validly-signed",
		"A validly signed payload that escapes '/' as \\/ is legal JSON but not the canonical (unescaped) form.",
		replaceOnce(t, p, "application/octet-stream", `application\/octet-stream`), "payload is not canonical JSON"))

	out = append(out, build("reject/payload-unicode-escape-validly-signed",
		"A validly signed payload that writes a printable ASCII character as a \\uXXXX escape is legal JSON but not the canonical (literal) form.",
		replaceOnce(t, p, "application/octet-stream", string(rune(0x5C))+"u0061pplication/octet-stream"), "payload is not canonical JSON"))

	out = append(out, build("reject/payload-duplicate-member-validly-signed",
		"Duplicating the payload's first member is rejected at the structural level before any canonical-form or field check.",
		replaceOnce(t, p, `"agent_id":"`+agentID+`",`, `"agent_id":"`+agentID+`","agent_id":"`+agentID+`",`), "duplicate JSON key"))

	out = append(out, build("reject/payload-number-validly-signed",
		"A JSON numeric token in place of the decimal-string artifact_size is rejected outright: 0.1 exact quantities are always strings.",
		replaceOnce(t, p, `"artifact_size":"0"`, `"artifact_size":0`), "numeric JSON values are unsupported"))

	out = append(out, build("reject/payload-null-member-validly-signed",
		"A null nonce is legal, canonical-stable JSON, but fails the required-field format check the same as an empty one.",
		replaceOnce(t, p, `"nonce":"`+nonceID+`"`, `"nonce":null`), "invalid origin statement"))

	out = append(out, build("reject/payload-missing-member-validly-signed",
		"Removing the nonce member entirely fails the required-field format check.",
		replaceOnce(t, p, `"nonce":"`+nonceID+`",`, ``), "invalid origin statement"))

	out = append(out, build("reject/payload-unknown-member-validly-signed",
		"An unknown member, even inserted at its correct canonical (sorted) position, is rejected by the closed payload schema.",
		replaceOnce(t, p, `,"protocol":"`+Protocol+`"}`, `,"protocol":"`+Protocol+`","zzz":"x"}`), "invalid JSON shape or field"))

	out = append(out, build("reject/payload-boolean-for-string-validly-signed",
		"A boolean value where the schema requires a string is legal, canonical-stable JSON, but a decode type mismatch.",
		replaceOnce(t, p, `"artifact_media_type":"application/octet-stream"`, `"artifact_media_type":true`), "invalid JSON shape or field"))

	// core-0.1.md: the root of a signed payload is a JSON object. Each of
	// these is canonical JSON under a real signature, so only that rule fails.
	for _, tc := range []struct{ name, root, wantErr string }{
		{"string", `"payload"`, "invalid canonical JSON input"},
		{"true", `true`, "invalid canonical JSON input"},
		{"null", `null`, "invalid canonical JSON input"},
		{"empty-array", `[]`, "invalid JSON shape or field"},
	} {
		out = append(out, build("reject/payload-root-"+tc.name+"-validly-signed",
			"The root of a signed payload must be a JSON object; "+tc.root+" is rejected even though it is canonical and validly signed.",
			[]byte(tc.root), tc.wantErr))
	}

	return out
}

// ---------------------------------------------------------------------------
// bundle_cases — reject: signature malleability (producerOnly base)
// ---------------------------------------------------------------------------

// ed25519GroupOrder is L, the prime order of the Ed25519 base point (RFC 8032
// section 5.1). A verifier must reject any signature whose scalar S is >= L.
const ed25519GroupOrder = "7237005577332262213973186563042994240857116359379907606001950938285454250989"

func reverseBytes(b []byte) []byte {
	out := make([]byte, len(b))
	for i := range b {
		out[i] = b[len(b)-1-i]
	}
	return out
}

func bundleSignatureMalleabilityCases(t *testing.T) []bundleCase {
	t.Helper()
	b, _ := producerOnly(t)
	if _, err := Verify(rawJSON(t, b), VerifyOptions{}); err != nil {
		t.Fatalf("producerOnly: unmutated bundle failed to verify: %v", err)
	}
	name := "reject/signature-s-plus-l-malleated"
	sig, err := rawURL.DecodeString(b.Statement.Signature.Value)
	requireNoErr(t, name, err)
	order, ok := new(big.Int).SetString(ed25519GroupOrder, 10)
	if !ok {
		t.Fatal("invalid Ed25519 group order constant")
	}
	// The scalar S is the little-endian second half of the signature. S+L
	// satisfies the same group equation, so only the RFC 8032 range check
	// S < L stands between a genuine signature and a second valid encoding.
	scalar := new(big.Int).Add(new(big.Int).SetBytes(reverseBytes(sig[32:])), order)
	malleated := append(append([]byte{}, sig[:32]...), reverseBytes(scalar.FillBytes(make([]byte, 32)))...)
	if bytes.Equal(malleated, sig) {
		t.Fatalf("%s: malleation did not change the signature", name)
	}
	bad := b
	bad.Statement.Signature.Value = rawURL.EncodeToString(malleated)
	return []bundleCase{rejectCase(t, name,
		"Adding the group order L to a genuine signature's scalar S yields a different encoding of the same group element; RFC 8032 requires S < L, so it is rejected.",
		rawJSON(t, bad), VerifyOptions{}, "invalid source signature")}
}

// ---------------------------------------------------------------------------
// bundle_cases — reject: signed field values (producerOnly base; the
// Statement struct is built with the bad value, then Canonical()-ed and
// signRaw-signed, so the payload is canonical and only the field rule can
// fire) plus the accept/media-type-128-bytes boundary case.
// ---------------------------------------------------------------------------

func bundleFieldValueCases(t *testing.T) []bundleCase {
	t.Helper()
	s := testSigner(t, 4)
	base := producerOnlyStatement(s)
	if _, err := Verify(rawJSON(t, Bundle{Protocol: Protocol, Statement: mustSign(t, s, KindStatement, base)}), VerifyOptions{}); err != nil {
		t.Fatalf("bundleFieldValueCases: unmutated base statement failed to verify: %v", err)
	}

	build := func(name, reason string, mutate func(*Statement), wantErr string) bundleCase {
		st := base
		mutate(&st)
		p, err := Canonical(st)
		requireNoErr(t, name, err)
		env := signRaw(t, s, KindStatement, p)
		return rejectCase(t, name, reason, rawJSON(t, Bundle{Protocol: Protocol, Statement: env}), VerifyOptions{}, wantErr)
	}

	var out []bundleCase

	for _, tc := range []struct{ name, value string }{
		{"reject/timestamp-fractional-seconds", "2026-09-13T00:00:00.000Z"},
		{"reject/timestamp-numeric-offset", "2026-09-13T00:00:00+00:00"},
		{"reject/timestamp-invalid-calendar-date", "2026-02-30T00:00:00Z"},
		{"reject/timestamp-lowercase", "2026-09-13t00:00:00z"},
		{"reject/timestamp-hour-24", "2026-09-13T24:00:00Z"},
		{"reject/timestamp-space-separator", "2026-09-13 00:00:00Z"},
		{"reject/timestamp-missing-zone", "2026-09-13T00:00:00"},
	} {
		value := tc.value
		out = append(out, build(tc.name, fmt.Sprintf("A statement issued_at of %q is not the exact UTC-seconds timestamp format the protocol requires.", value), func(st *Statement) {
			st.IssuedAt = value
		}, "timestamp must be UTC seconds"))
	}

	out = append(out, build("reject/uuid-uppercase",
		"An uppercase-hex agent_id is not a canonical lowercase UUID.",
		func(st *Statement) { st.AgentID = strings.ToUpper(agentID) }, "invalid origin statement"))
	out = append(out, build("reject/uuid-not-v4",
		"An agent_id whose version nibble is not 4 is not a valid UUID v4.",
		func(st *Statement) { st.AgentID = strings.Replace(agentID, "-4aaa-", "-1aaa-", 1) }, "invalid origin statement"))
	out = append(out, build("reject/uuid-bad-variant",
		"A nonce whose variant nibble is outside 8/9/a/b is not a valid UUID v4.",
		func(st *Statement) { st.Nonce = strings.Replace(nonceID, "-8bbb-", "-cbbb-", 1) }, "invalid origin statement"))
	out = append(out, build("reject/uuid-no-dashes",
		"A nonce without dashes is not a canonical UUID even though it is the same hex digits.",
		func(st *Statement) { st.Nonce = strings.ReplaceAll(nonceID, "-", "") }, "invalid origin statement"))

	for _, tc := range []struct{ name, value string }{
		{"reject/size-leading-zero", "00"},
		{"reject/size-negative", "-1"},
		{"reject/size-empty", ""},
		{"reject/size-too-long", strings.Repeat("1", 20)},
		{"reject/size-plus-sign", "+1"},
	} {
		value := tc.value
		out = append(out, build(tc.name, fmt.Sprintf("An artifact_size of %q does not match the required 0|[1-9][0-9]{0,18} decimal-string pattern.", value), func(st *Statement) {
			st.ArtifactSize = value
		}, "invalid origin statement"))
	}

	out = append(out, build("reject/digest-uppercase",
		"An uppercase-hex artifact_sha256 is not the required lowercase hex digest format.",
		func(st *Statement) { st.ArtifactSHA256 = strings.ToUpper(st.ArtifactSHA256) }, "invalid origin statement"))
	out = append(out, build("reject/digest-short",
		"A 63-character artifact_sha256 is one short of the required 64 hex characters.",
		func(st *Statement) { st.ArtifactSHA256 = st.ArtifactSHA256[:len(st.ArtifactSHA256)-1] }, "invalid origin statement"))

	out = append(out, build("reject/media-type-no-slash",
		"A media type without a '/' fails the required MIME-shape check.",
		func(st *Statement) { st.ArtifactMediaType = "textplain" }, "invalid origin statement"))
	out = append(out, build("reject/media-type-newline",
		"A media type containing a newline is rejected even though it is a well-formed JSON string.",
		func(st *Statement) { st.ArtifactMediaType = "text/plain\nx" }, "invalid origin statement"))

	longMediaType := strings.Repeat("a", 64) + "/" + strings.Repeat("a", 64)
	if len(longMediaType) != 129 {
		t.Fatalf("longMediaType fixture length = %d, want 129", len(longMediaType))
	}
	out = append(out, build("reject/media-type-too-long",
		"A 129-byte media type exceeds the 128-byte limit by one.",
		func(st *Statement) { st.ArtifactMediaType = longMediaType }, "invalid origin statement"))

	out = append(out, build("reject/source-issuer-not-signer-key",
		"A statement issuer identity that names a fabricated key instead of the actual signer's is rejected.",
		func(st *Statement) { st.Issuer = "urn:apostille:key:sha256:" + strings.Repeat("0", 64) }, "source issuer must identify agent key"))
	out = append(out, build("reject/signed-key-id-mismatch",
		"A statement issuer_key_id that does not match the envelope's real signing key is rejected.",
		func(st *Statement) { st.IssuerKeyID = testSigner(t, 1).KeyID() }, "signed key ID mismatch"))
	out = append(out, build("reject/payload-kind-mismatch",
		"A payload whose signed kind is agent-acceptance, carried inside an origin-statement envelope, is rejected: the envelope's real kind and the signed kind must match.",
		func(st *Statement) { st.Kind = KindAcceptance }, "invalid signed protocol header"))
	out = append(out, build("reject/payload-protocol-mismatch",
		"A payload with the wrong protocol identifier is rejected.",
		func(st *Statement) { st.Protocol = "https://ifandonlyif.io/apostille/spec/0.2" }, "invalid signed protocol header"))
	out = append(out, build("reject/missing-referenced-delegation",
		"A statement that claims a delegation digest while the bundle carries no delegation at all is rejected.",
		func(st *Statement) { st.DelegationSHA256 = Hash([]byte("some other delegation")) }, "missing referenced delegation"))

	mediaType128 := strings.Repeat("a", 64) + "/" + strings.Repeat("a", 63)
	if len(mediaType128) != 128 {
		t.Fatalf("mediaType128 fixture length = %d, want 128", len(mediaType128))
	}
	boundary := base
	boundary.ArtifactMediaType = mediaType128
	boundaryEnv := mustSign(t, s, KindStatement, boundary)
	bc, v := acceptCase(t, "accept/media-type-128-bytes", "A 128-byte media type is exactly at the limit and is accepted.", rawJSON(t, Bundle{Protocol: Protocol, Statement: boundaryEnv}), VerifyOptions{})
	if v.CertificateScope != "producer_only" || v.ArtifactIntegrity != "valid" {
		t.Fatalf("accept/media-type-128-bytes: unexpected verification: %+v", v)
	}
	out = append(out, bc)

	return out
}

// ---------------------------------------------------------------------------
// bundle_cases — reject: issuer identifier syntax inside a signed certificate
// (producerOnly + self-issued certificate via signRaw, all validly signed,
// options {})
// ---------------------------------------------------------------------------

func bundleCertificateIssuerSyntaxCases(t *testing.T) []bundleCase {
	t.Helper()
	base, s := producerOnly(t)

	build := func(name, reason, issuerValue string) bundleCase {
		b := base
		cert := certFor(t, b, s, issuerValue, fixedNow, fixedNow.Add(24*time.Hour), "eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee")
		p, err := Canonical(cert)
		requireNoErr(t, name, err)
		ce := signRaw(t, s, KindCertificate, p)
		b.Certificate = &ce
		return rejectCase(t, name, reason, rawJSON(t, b), VerifyOptions{}, "invalid signed protocol header")
	}

	return []bundleCase{
		build("reject/certificate-issuer-uppercase-host", "An uppercase host in the certificate issuer URL is rejected: HTTPS hosts must be lowercase.", "https://Issuer.example/a"),
		build("reject/certificate-issuer-default-port", "An explicit default port 443 is rejected: it must be omitted.", "https://issuer.example:443/a"),
		build("reject/certificate-issuer-noncanonical-port", "A port written with a leading zero is not the canonical decimal representation.", "https://issuer.example:0444/a"),
		build("reject/certificate-issuer-empty-port", "A trailing colon with no port number is rejected.", "https://issuer.example:/a"),
		build("reject/certificate-issuer-percent-escape", "A percent-escaped path is rejected: issuer identifiers are exact, unescaped bytes.", "https://issuer.example/a%20b"),
		build("reject/certificate-issuer-backslash", `A backslash in the issuer is rejected as an ambiguous character.`, `https://issuer.example/a\b`),
		build("reject/certificate-issuer-query-marker", "A trailing '?' is rejected: issuer identifiers may not carry a query.", "https://issuer.example/a?"),
		build("reject/certificate-issuer-fragment-marker", "A trailing '#' is rejected: issuer identifiers may not carry a fragment.", "urn:test#"),
		build("reject/certificate-issuer-http-scheme", "A plain http:// issuer is rejected: only https and opaque URNs are allowed.", "http://issuer.example"),
		build("reject/certificate-issuer-userinfo", "Embedded userinfo in the issuer URL is rejected.", "https://user@issuer.example/a"),
	}
}

// ---------------------------------------------------------------------------
// bundle_cases — reject: certificate assertions (fixedBundle, certificate
// rebuilt via signRaw, all validly signed, pin)
// ---------------------------------------------------------------------------

func bundleCertificateAssertionCases(t *testing.T) []bundleCase {
	t.Helper()
	b, _, _, issuer := fixedBundle(t)
	opts := pin(issuer)
	var cert Certificate
	requireNoErr(t, "bundleCertificateAssertionCases", DecodePayload(*b.Certificate, KindCertificate, &cert))

	build := func(name, reason string, mutate func(*Certificate), wantErr string) bundleCase {
		c := cert
		mutate(&c)
		p, err := Canonical(c)
		requireNoErr(t, name, err)
		ce := signRaw(t, issuer, KindCertificate, p)
		bad := b
		bad.Certificate = &ce
		return rejectCase(t, name, reason, rawJSON(t, bad), opts, wantErr)
	}

	out := []bundleCase{
		build("reject/certificate-content-truth-established",
			"A certificate asserting content_truth=established claims more than a 0.1 issuer may.",
			func(c *Certificate) { c.ContentTruth = "established" }, "unsupported certificate assertion"),
		build("reject/certificate-signature-check-invalid",
			"A certificate whose signature_check is not exactly 'valid' is rejected.",
			func(c *Certificate) { c.SignatureCheck = "invalid" }, "unsupported certificate assertion"),
		build("reject/certificate-organization-binding-verified",
			"A certificate asserting organization_binding=verified claims more than a 0.1 issuer may.",
			func(c *Certificate) { c.OrganizationBinding = "verified" }, "unsupported certificate assertion"),
	}

	// reject/certificate-agent-binding-unknown-value must NOT also carry a
	// nonempty delegation digest: on the delegated fixedBundle certificate,
	// an invalid agent_binding value simultaneously trips the "contradictory
	// certificate binding" check (since it isn't "admin_key_delegation"
	// while delegation_sha256 is nonempty), and that later check overwrites
	// the intended "unsupported certificate assertion" one. A producer-only
	// (delegation-free) self-issued certificate isolates the intended check.
	pOnly, signer4 := producerOnly(t)
	pCert := certFor(t, pOnly, signer4, "urn:example:private-issuer", fixedNow, fixedNow.Add(24*time.Hour), "eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee")
	pCert.AgentBinding = "unknown"
	pp, err := Canonical(pCert)
	requireNoErr(t, "reject/certificate-agent-binding-unknown-value", err)
	pce := signRaw(t, signer4, KindCertificate, pp)
	badAgentBinding := pOnly
	badAgentBinding.Certificate = &pce
	out = append(out, rejectCase(t, "reject/certificate-agent-binding-unknown-value",
		"A certificate agent_binding outside {admin_key_delegation, not_provided} is rejected, isolated on a delegation-free certificate so only that check can fire.",
		rawJSON(t, badAgentBinding), VerifyOptions{}, "unsupported certificate assertion"))

	out = append(out,
		build("reject/certificate-binding-contradiction",
			"A certificate claiming agent_binding=not_provided while still carrying a nonempty delegation digest is self-contradictory.",
			func(c *Certificate) { c.AgentBinding = "not_provided" }, "contradictory certificate binding"),
		build("reject/certificate-expiry-not-after-issue",
			"A certificate whose expires_at equals its issued_at does not satisfy expiry strictly after issuance.",
			func(c *Certificate) { c.ExpiresAt = c.IssuedAt }, "invalid validity interval"),
	)
	return out
}

// ---------------------------------------------------------------------------
// bundle_cases — reject: bindings (delegated chains, everything validly
// signed with mustSign; each payload is individually valid, only the
// relationship between envelopes is wrong)
// ---------------------------------------------------------------------------

// secondDelegation builds a second, differently-scoped delegation envelope
// with the same shape fixture(t) uses for the first one.
func secondDelegation(t *testing.T, admin, agent *Signer, agentID2, audience string) Envelope {
	t.Helper()
	d := Delegation{Header: NewHeader(KindDelegation, KeyIdentity(admin.KeyID()), admin, fixedNow), AgentID: agentID2, AgentKeyID: agent.KeyID(), AgentPublicKey: agent.PublicKey(), ServiceAudience: audience, NotBefore: fixedNow.Format(TimestampLayout), ExpiresAt: fixedNow.Add(48 * time.Hour).Format(TimestampLayout), Scopes: []string{"sign_origin_statement"}}
	return mustSign(t, admin, KindDelegation, d)
}

func bundleBindingCases(t *testing.T) []bundleCase {
	t.Helper()
	b, admin, agent, issuer := fixedBundle(t)
	opts := pin(issuer)
	signer4 := testSigner(t, 4)
	var out []bundleCase

	// certificate-grafted-onto-other-statement: re-sign the statement over a
	// different artifact hash and keep the old certificate, which still
	// references the original statement's digest.
	{
		var origStmt Statement
		requireNoErr(t, "certificate-grafted-onto-other-statement", DecodePayload(b.Statement, KindStatement, &origStmt))
		grafted := origStmt
		grafted.ArtifactSHA256 = Hash([]byte("grafted"))
		bad := b
		bad.Statement = mustSign(t, agent, KindStatement, grafted)
		out = append(out, rejectCase(t, "reject/certificate-grafted-onto-other-statement",
			"A statement re-signed over a different artifact hash no longer matches the certificate that was issued for the original statement.",
			rawJSON(t, bad), opts, "certificate is attached to the wrong source"))
	}

	out = append(out, rejectCase(t, "reject/envelope-kind-relabelled",
		"An envelope whose transport kind no longer says origin-statement is rejected before any signature or payload check.",
		mutateJSON(t, b, func(m map[string]any) {
			m["statement"].(map[string]any)["kind"] = KindCertificate
		}), opts, "wrong artifact kind"))

	// statement-by-undelegated-key: sign the statement with an unrelated key
	// that was never delegated, while still claiming the real delegation's
	// digest; rebuild the certificate with certFor so only the delegation
	// binding (not a stale certificate reference) is wrong.
	{
		var origStmt Statement
		requireNoErr(t, "statement-by-undelegated-key", DecodePayload(b.Statement, KindStatement, &origStmt))
		undelegated := origStmt
		undelegated.Header = NewHeader(KindStatement, KeyIdentity(signer4.KeyID()), signer4, fixedNow)
		bad := b
		bad.Statement = mustSign(t, signer4, KindStatement, undelegated)
		cert := certFor(t, bad, issuer, exampleIssuer, fixedNow.Add(time.Minute), fixedNow.Add(time.Minute+24*time.Hour), "cccccccc-cccc-4ccc-8ccc-cccccccccccc")
		ce := mustSign(t, issuer, KindCertificate, cert)
		bad.Certificate = &ce
		out = append(out, rejectCase(t, "reject/statement-by-undelegated-key",
			"A statement signed by a key that was never delegated, yet still claiming the real delegation's digest, is rejected: the delegated agent key does not match the signer.",
			rawJSON(t, bad), opts, "statement is not authorized by this delegation"))
	}

	// acceptance-for-other-delegation: a second delegation D2 with a
	// different agent_id; the acceptance binds D2's digest while the bundle
	// still carries D1.
	{
		d2 := secondDelegation(t, admin, agent, secondAgentID, exampleIssuer)
		d2h, err := EnvelopeDigest(d2)
		requireNoErr(t, "acceptance-for-other-delegation", err)
		a2 := Acceptance{Header: NewHeader(KindAcceptance, KeyIdentity(agent.KeyID()), agent, fixedNow), AgentID: secondAgentID, DelegationSHA256: d2h}
		bad := b
		a2Env := mustSign(t, agent, KindAcceptance, a2)
		bad.Acceptance = &a2Env
		out = append(out, rejectCase(t, "reject/acceptance-for-other-delegation",
			"An acceptance that binds a different delegation's digest than the one the bundle actually carries is rejected.",
			rawJSON(t, bad), opts, "agent proof is not bound to this delegation"))
	}

	// acceptance-by-wrong-key: the acceptance is signed by the administrator
	// instead of the delegated agent.
	{
		var origAcc Acceptance
		requireNoErr(t, "acceptance-by-wrong-key", DecodePayload(*b.Acceptance, KindAcceptance, &origAcc))
		wrongKey := origAcc
		wrongKey.Header = NewHeader(KindAcceptance, KeyIdentity(admin.KeyID()), admin, fixedNow)
		bad := b
		wrongKeyEnv := mustSign(t, admin, KindAcceptance, wrongKey)
		bad.Acceptance = &wrongKeyEnv
		out = append(out, rejectCase(t, "reject/acceptance-by-wrong-key",
			"An acceptance signed by the administrator key instead of the delegated agent key is rejected: proof of possession must come from the agent.",
			rawJSON(t, bad), opts, "agent proof is not bound to this delegation"))
	}

	// delegation-audience-mismatch: the delegation's service_audience names a
	// different service than the certificate issuer; acceptance, statement
	// and certificate are rebuilt consistently around it.
	{
		d3Env := secondDelegation(t, admin, agent, agentID, "https://other.example/apostille")
		d3h, err := EnvelopeDigest(d3Env)
		requireNoErr(t, "delegation-audience-mismatch", err)
		a3 := Acceptance{Header: NewHeader(KindAcceptance, KeyIdentity(agent.KeyID()), agent, fixedNow), AgentID: agentID, DelegationSHA256: d3h}
		a3Env := mustSign(t, agent, KindAcceptance, a3)
		st3 := Statement{Header: NewHeader(KindStatement, KeyIdentity(agent.KeyID()), agent, fixedNow), AgentID: agentID, DelegationSHA256: d3h, ArtifactSHA256: Hash([]byte("hello\n")), ArtifactSize: "6", ArtifactMediaType: "text/plain", Nonce: nonceID}
		st3Env := mustSign(t, agent, KindStatement, st3)
		bad := Bundle{Protocol: Protocol, Statement: st3Env, Delegation: &d3Env, Acceptance: &a3Env}
		cert := certFor(t, bad, issuer, exampleIssuer, fixedNow.Add(time.Minute), fixedNow.Add(time.Minute+24*time.Hour), "cccccccc-cccc-4ccc-8ccc-cccccccccccc")
		ce := mustSign(t, issuer, KindCertificate, cert)
		bad.Certificate = &ce
		out = append(out, rejectCase(t, "reject/delegation-audience-mismatch",
			"A delegation issued for a different service audience than the certificate issuer is rejected during certificate-time delegation validation.",
			rawJSON(t, bad), opts, "delegation audience mismatch"))
	}

	// certificate-source-key-mismatch: source_key_id names the administrator
	// key instead of the actual statement signer.
	{
		var cert Certificate
		requireNoErr(t, "certificate-source-key-mismatch", DecodePayload(*b.Certificate, KindCertificate, &cert))
		badCert := cert
		badCert.SourceKeyID = admin.KeyID()
		bad := b
		ce := mustSign(t, issuer, KindCertificate, badCert)
		bad.Certificate = &ce
		out = append(out, rejectCase(t, "reject/certificate-source-key-mismatch",
			"A certificate whose source_key_id names the administrator key instead of the actual statement signer is rejected.",
			rawJSON(t, bad), opts, "certificate is attached to the wrong source"))
	}

	// certificate-delegation-digest-mismatch: delegation_sha256 references a
	// different (unrelated) delegation than the one the statement cites.
	{
		other := secondDelegation(t, admin, agent, secondAgentID, exampleIssuer)
		otherDigest, err := EnvelopeDigest(other)
		requireNoErr(t, "certificate-delegation-digest-mismatch", err)
		var cert Certificate
		requireNoErr(t, "certificate-delegation-digest-mismatch", DecodePayload(*b.Certificate, KindCertificate, &cert))
		badCert := cert
		badCert.DelegationSHA256 = otherDigest
		bad := b
		ce := mustSign(t, issuer, KindCertificate, badCert)
		bad.Certificate = &ce
		out = append(out, rejectCase(t, "reject/certificate-delegation-digest-mismatch",
			"A certificate whose delegation_sha256 references a different delegation than the one the statement actually cites is rejected.",
			rawJSON(t, bad), opts, "certificate is attached to the wrong source"))
	}

	return out
}

// ---------------------------------------------------------------------------
// bundle_cases — time relationships (rebuild the whole chain with
// mustSign + certFor; pin unless noted)
// ---------------------------------------------------------------------------

func bundleTimeRelationshipCases(t *testing.T) []bundleCase {
	t.Helper()
	_, admin, agent, issuer := fixedBundle(t)
	opts := pin(issuer)

	// buildChain constructs a full delegated bundle from explicit
	// timestamps, all validly signed via mustSign/certFor.
	buildChain := func(delegNotBefore, delegExpires, delegIssued, acceptIssued, stmtIssued, certIssued, certExpires time.Time) Bundle {
		d := Delegation{Header: NewHeader(KindDelegation, KeyIdentity(admin.KeyID()), admin, delegIssued), AgentID: agentID, AgentKeyID: agent.KeyID(), AgentPublicKey: agent.PublicKey(), ServiceAudience: exampleIssuer, NotBefore: delegNotBefore.Format(TimestampLayout), ExpiresAt: delegExpires.Format(TimestampLayout), Scopes: []string{"sign_origin_statement"}}
		dEnv := mustSign(t, admin, KindDelegation, d)
		dh, err := EnvelopeDigest(dEnv)
		requireNoErr(t, "buildChain", err)
		a := Acceptance{Header: NewHeader(KindAcceptance, KeyIdentity(agent.KeyID()), agent, acceptIssued), AgentID: agentID, DelegationSHA256: dh}
		aEnv := mustSign(t, agent, KindAcceptance, a)
		st := Statement{Header: NewHeader(KindStatement, KeyIdentity(agent.KeyID()), agent, stmtIssued), AgentID: agentID, DelegationSHA256: dh, ArtifactSHA256: Hash([]byte("hello\n")), ArtifactSize: "6", ArtifactMediaType: "text/plain", Nonce: nonceID}
		stEnv := mustSign(t, agent, KindStatement, st)
		bundle := Bundle{Protocol: Protocol, Statement: stEnv, Delegation: &dEnv, Acceptance: &aEnv}
		cert := certFor(t, bundle, issuer, exampleIssuer, certIssued, certExpires, "cccccccc-cccc-4ccc-8ccc-cccccccccccc")
		ce := mustSign(t, issuer, KindCertificate, cert)
		bundle.Certificate = &ce
		return bundle
	}

	var out []bundleCase

	out = append(out, rejectCase(t, "reject/statement-after-certificate",
		"A statement claiming to be signed more than the allowed 120-second skew after the certificate's own issued_at is rejected.",
		rawJSON(t, buildChain(fixedNow, fixedNow.Add(48*time.Hour), fixedNow, fixedNow, fixedNow.Add(10*time.Minute), fixedNow.Add(time.Minute), fixedNow.Add(time.Minute+24*time.Hour))),
		opts, "certificate predates claimed source signature"))

	bc, v := acceptCase(t, "accept/statement-within-skew-of-certificate",
		"A statement issued exactly 120 seconds after the certificate's issued_at is at the inclusive edge of the allowed skew and is accepted.",
		rawJSON(t, buildChain(fixedNow, fixedNow.Add(48*time.Hour), fixedNow, fixedNow, fixedNow.Add(3*time.Minute), fixedNow.Add(time.Minute), fixedNow.Add(time.Minute+24*time.Hour))),
		opts)
	if v.IssuerTrust != "accepted_by_policy" || v.Freshness != "valid_at_evaluation_time" || v.ArtifactIntegrity != "valid" {
		t.Fatalf("accept/statement-within-skew-of-certificate: unexpected verification: %+v", v)
	}
	out = append(out, bc)

	out = append(out, rejectCase(t, "reject/delegation-expired-at-certificate-time",
		"A certificate issued after its delegation's expires_at is rejected: the delegation was no longer active at certificate-issuance time.",
		rawJSON(t, buildChain(fixedNow, fixedNow.Add(48*time.Hour), fixedNow, fixedNow, fixedNow, fixedNow.Add(49*time.Hour), fixedNow.Add(50*time.Hour))),
		opts, "delegation is not active at the evaluation time"))

	// Acceptance and statement sit exactly at not_before and the certificate
	// one minute earlier: inside the 120s source-time skew, so the only rule
	// broken is that the delegation is not yet active at certificate time.
	out = append(out, rejectCase(t, "reject/delegation-not-yet-active-at-certificate-time",
		"A certificate issued before its delegation's not_before is rejected: the delegation was not yet active at certificate-issuance time.",
		rawJSON(t, buildChain(fixedNow.Add(time.Hour), fixedNow.Add(time.Hour+48*time.Hour), fixedNow, fixedNow.Add(time.Hour), fixedNow.Add(time.Hour), fixedNow.Add(59*time.Minute), fixedNow.Add(59*time.Minute+24*time.Hour))),
		opts, "delegation is not active at the evaluation time"))

	out = append(out, rejectCase(t, "reject/certificate-outlives-delegation",
		"A certificate whose expires_at reaches past its delegation's expires_at exceeds the delegation's scope.",
		rawJSON(t, buildChain(fixedNow, fixedNow.Add(48*time.Hour), fixedNow, fixedNow, fixedNow, fixedNow.Add(time.Minute), fixedNow.Add(72*time.Hour))),
		opts, "certificate exceeds delegation scope"))

	out = append(out, rejectCase(t, "reject/statement-before-delegation-not-before",
		"A statement claiming to be signed before its delegation's not_before exceeds what the delegation could have authorized.",
		rawJSON(t, buildChain(fixedNow.Add(30*time.Minute), fixedNow.Add(30*time.Minute+48*time.Hour), fixedNow, fixedNow.Add(30*time.Minute), fixedNow, fixedNow.Add(31*time.Minute), fixedNow.Add(31*time.Minute+24*time.Hour))),
		opts, "certificate exceeds delegation scope"))

	out = append(out, rejectCase(t, "reject/acceptance-before-delegation-not-before",
		"An acceptance claiming to be signed before its delegation's not_before was not possible: the delegation did not exist yet at that time.",
		rawJSON(t, buildChain(fixedNow.Add(30*time.Minute), fixedNow.Add(30*time.Minute+48*time.Hour), fixedNow, fixedNow, fixedNow.Add(30*time.Minute), fixedNow.Add(31*time.Minute), fixedNow.Add(31*time.Minute+24*time.Hour))),
		opts, "delegation is not active at the evaluation time"))

	// delegation-interval-inverted: expires_at == not_before is refused by
	// mustSign's own validation (interval() requires strictly-after), so the
	// delegation must be validly signed via signRaw instead.
	{
		badDeleg := Delegation{Header: NewHeader(KindDelegation, KeyIdentity(admin.KeyID()), admin, fixedNow), AgentID: agentID, AgentKeyID: agent.KeyID(), AgentPublicKey: agent.PublicKey(), ServiceAudience: exampleIssuer, NotBefore: fixedNow.Format(TimestampLayout), ExpiresAt: fixedNow.Format(TimestampLayout), Scopes: []string{"sign_origin_statement"}}
		dp, err := Canonical(badDeleg)
		requireNoErr(t, "delegation-interval-inverted", err)
		dEnv := signRaw(t, admin, KindDelegation, dp)
		dh, err := EnvelopeDigest(dEnv)
		requireNoErr(t, "delegation-interval-inverted", err)
		a := Acceptance{Header: NewHeader(KindAcceptance, KeyIdentity(agent.KeyID()), agent, fixedNow), AgentID: agentID, DelegationSHA256: dh}
		aEnv := mustSign(t, agent, KindAcceptance, a)
		st := Statement{Header: NewHeader(KindStatement, KeyIdentity(agent.KeyID()), agent, fixedNow), AgentID: agentID, DelegationSHA256: dh, ArtifactSHA256: Hash([]byte("hello\n")), ArtifactSize: "6", ArtifactMediaType: "text/plain", Nonce: nonceID}
		stEnv := mustSign(t, agent, KindStatement, st)
		bad := Bundle{Protocol: Protocol, Statement: stEnv, Delegation: &dEnv, Acceptance: &aEnv}
		out = append(out, rejectCase(t, "reject/delegation-interval-inverted",
			"A delegation whose expires_at equals its not_before, rather than strictly after, is individually invalid even though it is validly signed.",
			rawJSON(t, bad), opts, "invalid validity interval"))
	}

	return out
}

// ---------------------------------------------------------------------------
// bundle_cases — reject: whole input
// ---------------------------------------------------------------------------

func bundleWholeInputCases(t *testing.T) []bundleCase {
	t.Helper()
	b, _, _, _ := fixedBundle(t)
	canonical := rawJSON(t, b)
	opts := VerifyOptions{}
	var out []bundleCase

	out = append(out, rejectCase(t, "reject/input-empty",
		"An empty input has no JSON to parse.",
		[]byte{}, opts, "invalid JSON size or UTF-8"))

	{
		bad := append([]byte{}, canonical...)
		idx := bytes.Index(bad, []byte("ifandonlyif"))
		if idx < 0 {
			t.Fatal("reject/input-invalid-utf8: marker text not found in canonical bundle")
		}
		bad[idx] = 0xFF
		out = append(out, rejectCase(t, "reject/input-invalid-utf8",
			"A single invalid UTF-8 byte inside an otherwise well-formed bundle string is rejected before any JSON parsing.",
			bad, opts, "invalid JSON size or UTF-8"))
	}

	out = append(out, rejectCase(t, "reject/input-utf8-bom",
		"A UTF-8 BOM before the bundle is not insignificant JSON whitespace and is rejected as malformed.",
		append([]byte("\xEF\xBB\xBF"), canonical...), opts, "invalid JSON"))

	out = append(out, rejectCase(t, "reject/input-trailing-data",
		"A second complete JSON value after the bundle is rejected as trailing data.",
		append(append([]byte{}, canonical...), []byte("{}")...), opts, "trailing JSON"))

	out = append(out, rejectCase(t, "reject/input-trailing-garbage",
		"A stray non-JSON byte after the bundle is rejected as trailing data.",
		append(append([]byte{}, canonical...), 'x'), opts, "trailing JSON"))

	out = append(out, rejectCase(t, "reject/input-top-level-array",
		"A bundle wrapped in a top-level array is not the expected object shape.",
		append(append([]byte("["), canonical...), ']'), opts, "invalid JSON shape or field"))

	// core-0.1.md: the root of a bundle is a JSON object. The parsing helpers
	// differ on whether a scalar is JSON at all, so the rule is pinned where
	// it matters, at the verification entry point.
	for _, tc := range []struct{ name, root, wantErr string }{
		{"string", `"bundle"`, "invalid canonical JSON input"},
		{"true", `true`, "invalid canonical JSON input"},
		{"null", `null`, "invalid canonical JSON input"},
		{"empty-array", `[]`, "invalid JSON shape or field"},
	} {
		out = append(out, rejectCase(t, "reject/input-root-"+tc.name,
			"The root of a bundle must be a JSON object; "+tc.root+" is rejected.",
			[]byte(tc.root), opts, tc.wantErr))
	}

	out = append(out, rejectCase(t, "reject/input-depth-26",
		"26 levels of array nesting exceeds the protocol's maximum JSON depth of 24.",
		[]byte(strings.Repeat("[", 26)+"true"+strings.Repeat("]", 26)), opts, "JSON nesting exceeds 24"))

	gen := inputGen{RepeatB64: rawURL.EncodeToString([]byte(" ")), Count: MaxInputBytes + 1}
	decoded := bytes.Repeat([]byte(" "), gen.Count)
	out = append(out, rejectGenCase(t, "reject/input-oversize",
		"An input one byte over the 262144-byte maximum is rejected outright, before any parsing is attempted.",
		gen, decoded, opts, "invalid JSON size"))

	return out
}

// ---------------------------------------------------------------------------
// strict_json_cases
// ---------------------------------------------------------------------------

// backslash is the literal ASCII backslash byte, built numerically so source
// text never has to carry an ambiguous literal backslash character.
const backslash = byte(0x5C)

// jsonUnicodeEscape returns the 6-byte JSON \uXXXX escape sequence for the
// given 4 lowercase hex digits.
func jsonUnicodeEscape(hex4 string) []byte {
	if len(hex4) != 4 {
		panic("jsonUnicodeEscape: need exactly 4 hex digits")
	}
	return append([]byte{backslash, 'u'}, []byte(hex4)...)
}

// jsonCharEscape returns the 2-byte JSON escape sequence \c for a character
// that has a single-letter JSON escape (n, r, t, b, f, /, \, ").
func jsonCharEscape(c byte) []byte { return []byte{backslash, c} }

var jsonTextToken = regexp.MustCompile(`<([0-9a-fA-F]{4}|bs|rocket|replacement)>`)

// jsonText expands tokens into the exact bytes they name: <hhhh> is the JSON
// escape of that UTF-16 code unit, <bs> one backslash, <rocket> the UTF-8 of
// U+1F680 and <replacement> the UTF-8 of U+FFFD. Test inputs are spelled this
// way so that nothing which handles this file can decode an escape into the
// character it names, or the reverse.
func jsonText(s string) []byte {
	return jsonTextToken.ReplaceAllFunc([]byte(s), func(m []byte) []byte {
		switch token := string(m[1 : len(m)-1]); token {
		case "bs":
			return []byte{backslash}
		case "rocket":
			return []byte{0xf0, 0x9f, 0x9a, 0x80}
		case "replacement":
			return []byte{0xef, 0xbf, 0xbd}
		default:
			return jsonUnicodeEscape(token)
		}
	})
}

func strictJSONRejectCases(t *testing.T) []strictJSONCase {
	t.Helper()

	build := func(name, reason string, raw []byte) strictJSONCase {
		t.Helper()
		var dst any
		if err := StrictJSON(raw, &dst); err == nil {
			t.Fatalf("%s: expected reject, got accept", name)
		}
		return strictJSONCase{Name: name, Reason: reason, InputB64: strPtr(rawURL.EncodeToString(raw)), Expect: "reject"}
	}

	var out []strictJSONCase

	out = append(out, build("reject/duplicate-member",
		"Two members with the literally identical name are rejected.",
		[]byte(`{"a":true,"a":false}`)))

	escapedDup := append([]byte(`{"a":true,"`), jsonUnicodeEscape("0061")...)
	escapedDup = append(escapedDup, []byte(`":false}`)...)
	out = append(out, build("reject/duplicate-member-escaped-equivalent",
		"A second member name written as a unicode escape that decodes to the same string as the first is rejected: duplicate detection compares decoded values, not literal escape text.",
		escapedDup))

	out = append(out, build("reject/number",
		"A bare JSON number value is rejected: 0.1 exact quantities are always decimal strings, never JSON numbers.",
		[]byte(`{"n":1}`)))
	out = append(out, build("reject/number-in-array",
		"A JSON number nested inside an array is rejected the same as a number anywhere else.",
		[]byte(`[1]`)))
	out = append(out, build("reject/negative-zero",
		"The bare numeric literal -0 is rejected: numbers are unsupported as any JSON value, not just inside objects.",
		[]byte(`-0`)))

	highSurrogate := append([]byte(`{"x":"`), jsonUnicodeEscape("d800")...)
	highSurrogate = append(highSurrogate, []byte(`"}`)...)
	out = append(out, build("reject/lone-high-surrogate", "An unpaired UTF-16 high surrogate escape is not valid Unicode text and is rejected.", highSurrogate))

	lowSurrogate := append([]byte(`{"x":"`), jsonUnicodeEscape("dc00")...)
	lowSurrogate = append(lowSurrogate, []byte(`"}`)...)
	out = append(out, build("reject/lone-low-surrogate", "An unpaired UTF-16 low surrogate escape is not valid Unicode text and is rejected.", lowSurrogate))

	// A surrogate escape is valid only as a high+low pair. Two consecutive
	// unpaired escapes are the forms a parser that merely expects "another \u
	// escape" lets through and then decodes to U+FFFD, so each is pinned in a
	// value and in a member name.
	for _, tc := range []struct{ name, text, reason string }{
		{"low-then-high", "<dc00><d800>", "A low surrogate followed by a high surrogate is two unpaired surrogates, not a reversed pair."},
		{"high-then-high", "<d800><d800>", "Two high surrogates in a row are both unpaired."},
		{"low-then-low", "<dc00><dc00>", "Two low surrogates in a row are both unpaired."},
		{"high-then-bmp-escape", "<d800><0041>", "A high surrogate followed by the escape of an ordinary character is unpaired."},
		{"high-then-literal", "<d800>A", "A high surrogate followed by a literal character is unpaired."},
		{"pair-then-lone-high", "<d83d><de80><d800>", "A valid pair does not excuse an unpaired surrogate after it."},
		{"lone-high-uppercase-hex", "<D800>", "Hex digits of an escape are case-insensitive; an uppercase unpaired surrogate is still unpaired."},
		{"escaped-backslash-then-lone-high", "<bs><bs><d800>", "An escaped backslash followed by a real surrogate escape: three backslashes, so the escape is live and unpaired."},
	} {
		out = append(out, build("reject/surrogate-"+tc.name, tc.reason, jsonText(`{"x":"`+tc.text+`"}`)))
		out = append(out, build("reject/surrogate-"+tc.name+"-in-member-name", tc.reason+" Member names follow the same rule as values.", jsonText(`{"`+tc.text+`":true}`)))
	}

	out = append(out, build("reject/trailing-comma", "A trailing comma before the closing bracket is not valid JSON array syntax.", []byte(`[true,]`)))
	out = append(out, build("reject/two-values", "Two complete top-level JSON values with no separator are rejected as trailing data.", []byte(`{}{}`)))
	out = append(out, build("reject/value-then-object", "A top-level value followed by whitespace and a second value is rejected as trailing data.", []byte(`{"x":true} {}`)))
	out = append(out, build("reject/depth-25", "25 levels of array nesting is one past the protocol's maximum JSON depth of 24.", []byte(strings.Repeat("[", 25)+"true"+strings.Repeat("]", 25))))
	out = append(out, build("reject/depth-26", "26 levels of array nesting exceeds the protocol's maximum JSON depth of 24.", []byte(strings.Repeat("[", 26)+"true"+strings.Repeat("]", 26))))

	{
		gen := inputGen{RepeatB64: rawURL.EncodeToString([]byte(" ")), Count: MaxInputBytes + 1}
		decoded := bytes.Repeat([]byte(" "), gen.Count)
		var dst any
		if err := StrictJSON(decoded, &dst); err == nil {
			t.Fatal("reject/oversize: expected reject, got accept")
		}
		out = append(out, strictJSONCase{Name: "reject/oversize", Reason: "An input one byte over the 262144-byte maximum is rejected outright, before any parsing is attempted.", InputGen: &gen, Expect: "reject"})
	}

	invalidUTF8 := append([]byte(`{"x":"`), 0xFF)
	invalidUTF8 = append(invalidUTF8, []byte(`"}`)...)
	out = append(out, build("reject/invalid-utf8", "A raw invalid UTF-8 byte inside a string value is rejected before any JSON parsing.", invalidUTF8))

	out = append(out, build("reject/utf8-bom", "A UTF-8 BOM before the value is not insignificant JSON whitespace and is rejected as malformed.", append([]byte("\xEF\xBB\xBF"), []byte(`{}`)...)))
	out = append(out, build("reject/empty-input", "An empty input has no JSON to parse.", []byte{}))
	out = append(out, build("reject/single-quote-string", "Single-quoted strings are not valid JSON; only double quotes delimit strings.", []byte(`{'a':true}`)))

	unescapedControl := append([]byte(`{"x":"`), 0x01)
	unescapedControl = append(unescapedControl, []byte(`"}`)...)
	out = append(out, build("reject/unescaped-control-char", "A raw, unescaped control byte inside a string is not valid JSON: control characters below U+0020 must be escaped.", unescapedControl))

	out = append(out, build("reject/leading-zero-number", "A number with a leading zero followed by more digits is not valid JSON number syntax.", []byte(`01`)))
	out = append(out, build("reject/bare-word", "An incomplete literal ('nul' rather than 'null') is not a recognized JSON token.", []byte(`nul`)))

	return out
}

func strictJSONAcceptCases(t *testing.T) []strictJSONCase {
	t.Helper()

	build := func(name, reason string, raw []byte) strictJSONCase {
		t.Helper()
		var dst any
		if err := StrictJSON(raw, &dst); err != nil {
			t.Fatalf("%s: expected accept, got error: %v", name, err)
		}
		canonical, err := Canonical(dst)
		requireNoErr(t, name, err)
		return strictJSONCase{Name: name, Reason: reason, InputB64: strPtr(rawURL.EncodeToString(raw)), Expect: "accept", CanonicalB64: strPtr(rawURL.EncodeToString(canonical))}
	}

	var out []strictJSONCase

	surrogatePair := append([]byte(`{"x":"`), jsonUnicodeEscape("d83d")...)
	surrogatePair = append(surrogatePair, jsonUnicodeEscape("de80")...)
	surrogatePair = append(surrogatePair, []byte(`"}`)...)
	rocket := build("accept/surrogate-pair-escape", "A UTF-16 surrogate pair escape decodes to one astral character; canonical form uses the raw 4-byte UTF-8 encoding, not the escape.", surrogatePair)
	if want := rawURL.EncodeToString([]byte(`{"x":"🚀"}`)); *rocket.CanonicalB64 != want {
		t.Fatalf("accept/surrogate-pair-escape: canonical b64 = %q, want %q", *rocket.CanonicalB64, want)
	}
	out = append(out, rocket)

	// The unpaired-surrogate rule must not over-reject: valid pairs, U+FFFD
	// written literally or as an escape, and the text "ud800" behind an escaped
	// backslash are all ordinary strings.
	for _, tc := range []struct{ name, reason, input, canonical string }{
		{"accept/surrogate-pair-uppercase-hex", "Hex digits of an escape are case-insensitive; an uppercase pair is a valid pair.", `{"x":"<D83D><DE80>"}`, `{"x":"<rocket>"}`},
		{"accept/surrogate-pair-in-member-name", "A valid pair in a member name decodes to one astral character.", `{"<d83d><de80>":true}`, `{"<rocket>":true}`},
		{"accept/two-surrogate-pairs", "Consecutive escapes are fine when they form complete pairs.", `{"x":"<d83d><de80><d83d><de80>"}`, `{"x":"<rocket><rocket>"}`},
		{"accept/replacement-character-literal", "A literal U+FFFD is an ordinary character, not evidence of a decoding error.", `{"x":"<replacement>"}`, `{"x":"<replacement>"}`},
		{"accept/replacement-character-escape", "The escape of U+FFFD is not a surrogate; it canonicalizes to the literal character.", `{"x":"<fffd>"}`, `{"x":"<replacement>"}`},
		{"accept/escaped-backslash-then-surrogate-text", "Two backslashes are one escaped backslash, so the following ud800 is plain text, not an escape.", `{"x":"<bs><bs>ud800"}`, `{"x":"<bs><bs>ud800"}`},
		{"accept/two-escaped-backslashes-then-surrogate-text", "Four backslashes are two escaped backslashes; the following ud800 is still plain text.", `{"x":"<bs><bs><bs><bs>ud800"}`, `{"x":"<bs><bs><bs><bs>ud800"}`},
	} {
		c := build(tc.name, tc.reason, jsonText(tc.input))
		if want := rawURL.EncodeToString(jsonText(tc.canonical)); *c.CanonicalB64 != want {
			t.Fatalf("%s: canonical b64 = %q, want %q", tc.name, *c.CanonicalB64, want)
		}
		out = append(out, c)
	}

	// core-0.1.md: "depth at most 24". Paired with reject/depth-25 so the
	// exact boundary is pinned on both sides.
	out = append(out, build("accept/depth-24-boundary",
		"24 levels of array nesting is the largest depth accepted; one more is rejected.",
		[]byte(strings.Repeat("[", 24)+"true"+strings.Repeat("]", 24))))

	mixedInput := append([]byte(`{"z":"中","😀":"x","a":"`), jsonCharEscape('n')...)
	mixedInput = append(mixedInput, []byte(`"}`)...)
	mixed := build("accept/mixed-scripts-sorting", "Object members sort by UTF-16 code unit order of the key, not by script, code point or byte order.", mixedInput)
	{
		canonicalBytes, err := rawURL.DecodeString(*mixed.CanonicalB64)
		requireNoErr(t, "accept/mixed-scripts-sorting", err)
		posA := bytes.Index(canonicalBytes, []byte(`"a"`))
		posZ := bytes.Index(canonicalBytes, []byte(`"z"`))
		posEmoji := bytes.Index(canonicalBytes, []byte(`"😀"`))
		if posA < 0 || posZ < 0 || posEmoji < 0 || !(posA < posZ && posZ < posEmoji) {
			t.Fatalf("accept/mixed-scripts-sorting: unexpected key order in %s", canonicalBytes)
		}
	}
	out = append(out, mixed)

	utf16Case := build("accept/utf16-code-unit-order",
		"RFC 8785 section 3.2.3 orders object keys by UTF-16 code unit sequence, not code point or UTF-8 byte order: this is a well-known canonicalization trap. \xF0\x9F\x98\x80's leading surrogate (U+D83D) sorts before \xEF\xBD\x9E's single code unit (U+FF5E) even though code-point order and UTF-8 byte order both disagree.",
		[]byte(`{"～":true,"😀":true}`))
	{
		canonicalBytes, err := rawURL.DecodeString(*utf16Case.CanonicalB64)
		requireNoErr(t, "accept/utf16-code-unit-order", err)
		posEmoji := bytes.Index(canonicalBytes, []byte(`"😀"`))
		posTilde := bytes.Index(canonicalBytes, []byte(`"～"`))
		if posEmoji < 0 || posTilde < 0 || !(posEmoji < posTilde) {
			t.Fatalf("accept/utf16-code-unit-order: expected the emoji key before the tilde key in %s", canonicalBytes)
		}
	}
	out = append(out, utf16Case)

	htmlCase := build("accept/html-chars-unescaped", "Canonical JSON only escapes what RFC 8785 requires; '<', '>' and '&' are ordinary printable ASCII and are left unescaped.", []byte(`{"x":"<>&"}`))
	{
		canonicalBytes, err := rawURL.DecodeString(*htmlCase.CanonicalB64)
		requireNoErr(t, "accept/html-chars-unescaped", err)
		if !bytes.Contains(canonicalBytes, []byte(`<>&`)) {
			t.Fatalf("accept/html-chars-unescaped: expected literal <>& in %s", canonicalBytes)
		}
	}
	out = append(out, htmlCase)

	ctrlInput := []byte(`{"x":"`)
	ctrlInput = append(ctrlInput, jsonUnicodeEscape("0008")...)
	ctrlInput = append(ctrlInput, jsonUnicodeEscape("000c")...)
	ctrlInput = append(ctrlInput, jsonCharEscape('n')...)
	ctrlInput = append(ctrlInput, jsonCharEscape('r')...)
	ctrlInput = append(ctrlInput, jsonCharEscape('t')...)
	ctrlInput = append(ctrlInput, jsonUnicodeEscape("001f")...)
	ctrlInput = append(ctrlInput, jsonUnicodeEscape("007f")...)
	ctrlInput = append(ctrlInput, []byte(`"}`)...)
	ctrlCase := build("accept/control-escapes", "Canonical JSON uses the named two-character escapes for backspace/form-feed/newline/CR/tab, lowercase-hex \\u001f for the unit separator (no named escape exists), and leaves DEL (0x7F) as a raw unescaped byte: only U+0000-U+001F must be escaped.", ctrlInput)
	{
		canonicalBytes, err := rawURL.DecodeString(*ctrlCase.CanonicalB64)
		requireNoErr(t, "accept/control-escapes", err)
		want := []byte(`{"x":"`)
		want = append(want, jsonCharEscape('b')...)
		want = append(want, jsonCharEscape('f')...)
		want = append(want, jsonCharEscape('n')...)
		want = append(want, jsonCharEscape('r')...)
		want = append(want, jsonCharEscape('t')...)
		want = append(want, jsonUnicodeEscape("001f")...)
		want = append(want, 0x7F)
		want = append(want, []byte(`"}`)...)
		if !bytes.Equal(canonicalBytes, want) {
			t.Fatalf("accept/control-escapes: canonical = %q, want %q", canonicalBytes, want)
		}
	}
	out = append(out, ctrlCase)

	solidusInput := append([]byte(`{"x":"a`), jsonCharEscape('/')...)
	solidusInput = append(solidusInput, []byte(`b"}`)...)
	solidusCase := build("accept/escaped-solidus-normalised", "An escaped solidus is legal JSON but canonicalizes to the literal, unescaped '/'.", solidusInput)
	if want := rawURL.EncodeToString([]byte(`{"x":"a/b"}`)); *solidusCase.CanonicalB64 != want {
		t.Fatalf("accept/escaped-solidus-normalised: canonical b64 = %q, want %q", *solidusCase.CanonicalB64, want)
	}
	out = append(out, solidusCase)

	wsCase := build("accept/outer-whitespace", "Insignificant whitespace around tokens is legal JSON and does not affect the canonical result.", []byte(` { "a" : [ true , null ] } `))
	if want := rawURL.EncodeToString([]byte(`{"a":[true,null]}`)); *wsCase.CanonicalB64 != want {
		t.Fatalf("accept/outer-whitespace: canonical b64 = %q, want %q", *wsCase.CanonicalB64, want)
	}
	out = append(out, wsCase)

	literalsCase := build("accept/literals", "The bare literal array [true,false,null] is already canonical.", []byte(`[true,false,null]`))
	if want := rawURL.EncodeToString([]byte(`[true,false,null]`)); *literalsCase.CanonicalB64 != want {
		t.Fatalf("accept/literals: canonical b64 = %q, want %q", *literalsCase.CanonicalB64, want)
	}
	out = append(out, literalsCase)

	emptyObjCase := build("accept/empty-object", "The empty object {} is already canonical.", []byte(`{}`))
	if want := rawURL.EncodeToString([]byte(`{}`)); *emptyObjCase.CanonicalB64 != want {
		t.Fatalf("accept/empty-object: canonical b64 = %q, want %q", *emptyObjCase.CanonicalB64, want)
	}
	out = append(out, emptyObjCase)

	emptyKeyCase := build("accept/empty-string-key", "An empty string key is legal JSON and round-trips through canonicalization unchanged.", []byte(`{"":""}`))
	if want := rawURL.EncodeToString([]byte(`{"":""}`)); *emptyKeyCase.CanonicalB64 != want {
		t.Fatalf("accept/empty-string-key: canonical b64 = %q, want %q", *emptyKeyCase.CanonicalB64, want)
	}
	out = append(out, emptyKeyCase)

	return out
}

// ---------------------------------------------------------------------------
// issuer_cases (exercised via ValidIssuer)
// ---------------------------------------------------------------------------

func issuerConformanceCaseList(t *testing.T) []issuerConformanceCase {
	t.Helper()

	build := func(value string, wantAccept bool) issuerConformanceCase {
		got := ValidIssuer(value)
		if got != wantAccept {
			t.Fatalf("issuer %q: ValidIssuer = %v, want %v", value, got, wantAccept)
		}
		expect := "reject"
		if wantAccept {
			expect = "accept"
		}
		return issuerConformanceCase{Value: value, Expect: expect}
	}

	long256 := "https://issuer.example/" + strings.Repeat("a", 233)
	if len(long256) != 256 {
		t.Fatalf("long256 fixture length = %d, want 256", len(long256))
	}
	long257 := "https://issuer.example/" + strings.Repeat("a", 234)
	if len(long257) != 257 {
		t.Fatalf("long257 fixture length = %d, want 257", len(long257))
	}
	backslashPath := "https://issuer.example/a" + string(rune(0x5C)) + "b"

	var out []issuerConformanceCase
	for _, tc := range []struct {
		value  string
		accept bool
	}{
		{"https://issuer.example/apostille", true},
		{"https://issuer.example", true},
		{"https://issuer.example:8443/a", true},
		{"urn:example:private-issuer", true},
		{"urn:apostille:key:sha256:" + strings.Repeat("0", 64), true},
		{long256, true},

		{"", false},
		{"https://Issuer.example/a", false},
		{"https://ISSUER.EXAMPLE:8443/a", false},
		{"https://issuer.example:443/a", false},
		{"https://issuer.example:443", false},
		{"https://issuer.example:0444/a", false},
		{"https://issuer.example:08443/a", false},
		{"https://issuer.example:+8443/a", false},
		{"https://issuer.example:/a", false},
		{"https://issuer.example:65536/a", false},
		{"https://issuer.example/a%20b", false},
		{"urn:example:a%41", false},
		{backslashPath, false},
		{"https://issuer.example/a?", false},
		{"urn:test#", false},
		{"http://issuer.example", false},
		{"ftp://issuer.example/a", false},
		{"https://user@issuer.example/a", false},
		{"https://user:pw@issuer.example/a", false},
		{" https://issuer.example/a", false},
		{"https://issuer.example/a ", false},
		{"urn:example:x y", false},
		{"https://issuer.example/é", false},
		{"https://é.example/a", false},
		{"https://", false},
		{"https:///a", false},
		{"issuer.example/a", false},
		{"//issuer.example/a", false},
		{"urn:", false},
		{long257, false},
	} {
		out = append(out, build(tc.value, tc.accept))
	}
	return out
}

// ---------------------------------------------------------------------------
// TestWriteConformanceCases / TestConformanceCases
