func checkUniqueBundleNames(t *testing.T, cases []bundleCase) {
	t.Helper()
	seen := map[string]bool{}
	for _, c := range cases {
		if seen[c.Name] {
			t.Fatalf("duplicate bundle case name: %s", c.Name)
		}
		seen[c.Name] = true
	}
}

func checkUniqueStrictNames(t *testing.T, cases []strictJSONCase) {
	t.Helper()
	seen := map[string]bool{}
	for _, c := range cases {
		if seen[c.Name] {
			t.Fatalf("duplicate strict_json case name: %s", c.Name)
		}
		seen[c.Name] = true
	}
}

// verifyTiesToInteropFixture asserts the delegated base bundle this file's
// cases are built from is byte-identical (once canonicalized) to the bundle
// member of testdata/apostille/core-0.1.json, tying the two files together.
func verifyTiesToInteropFixture(t *testing.T) {
	t.Helper()
	b, _, _, _ := fixedBundle(t)
	existing, err := os.ReadFile(filepath.Join("..", "testdata", "apostille", "core-0.1.json"))
	if err != nil {
		t.Fatal(err)
	}
	var fixtureFile struct {
		Bundle Bundle `json:"bundle"`
	}
	if err := json.Unmarshal(existing, &fixtureFile); err != nil {
		t.Fatal(err)
	}
	a, err := Canonical(b)
	requireNoErr(t, "verifyTiesToInteropFixture", err)
	want, err := Canonical(fixtureFile.Bundle)
	requireNoErr(t, "verifyTiesToInteropFixture", err)
	if !bytes.Equal(a, want) {
		t.Fatalf("fixedBundle diverges from testdata/apostille/core-0.1.json's bundle member")
	}
}

func TestWriteConformanceCases(t *testing.T) {
	verifyTiesToInteropFixture(t)

	var bundleCases []bundleCase
	bundleCases = append(bundleCases, bundleAcceptCases(t)...)
	bundleCases = append(bundleCases, bundleTamperingCases(t)...)
	bundleCases = append(bundleCases, bundleStructureCases(t)...)
	bundleCases = append(bundleCases, bundlePayloadEncodingCases(t)...)
	bundleCases = append(bundleCases, bundleSignatureMalleabilityCases(t)...)
	bundleCases = append(bundleCases, bundleFieldValueCases(t)...)
	bundleCases = append(bundleCases, bundleCertificateIssuerSyntaxCases(t)...)
	bundleCases = append(bundleCases, bundleCertificateAssertionCases(t)...)
	bundleCases = append(bundleCases, bundleBindingCases(t)...)
	bundleCases = append(bundleCases, bundleTimeRelationshipCases(t)...)
	bundleCases = append(bundleCases, bundleWholeInputCases(t)...)
	checkUniqueBundleNames(t, bundleCases)

	var strictCases []strictJSONCase
	strictCases = append(strictCases, strictJSONRejectCases(t)...)
	strictCases = append(strictCases, strictJSONAcceptCases(t)...)
	checkUniqueStrictNames(t, strictCases)

	issuerCases := issuerConformanceCaseList(t)

	if len(bundleCases) == 0 {
		t.Fatal("no bundle cases generated")
	}
	if len(strictCases) == 0 {
		t.Fatal("no strict_json cases generated")
	}
	if len(issuerCases) == 0 {
		t.Fatal("no issuer cases generated")
	}

	file := conformanceFile{
		Protocol:        conformanceProtocol,
		Format:          conformanceFormat,
		Notice:          conformanceNotice,
		BundleCases:     bundleCases,
		StrictJSONCases: strictCases,
		IssuerCases:     issuerCases,
	}
	raw, err := json.MarshalIndent(file, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	raw = append(raw, '\n')
	path := filepath.Join("..", "testdata", "apostille", "core-0.1-cases.json")
	if os.Getenv("UPDATE_APOSTILLE_FIXTURES") == "1" {
		if err := os.WriteFile(path, raw, 0644); err != nil {
			t.Fatal(err)
		}
	}
	existing, err := os.ReadFile(path)
	if err != nil || !bytes.Equal(existing, raw) {
		t.Fatal("fixture mismatch; run UPDATE_APOSTILLE_FIXTURES=1 GOWORK=off go test -run 'TestWriteConformanceCases' -count=1 ./apostille to regenerate")
	}
}

// ---------------------------------------------------------------------------
// TestConformanceCases — an INDEPENDENT consumer. It declares its own plain
// structs for the on-disk JSON shape and shares no case-building code (no
// helpers, no case-construction functions) with the generator above; it only
// calls the public API. This is deliberately close to how a from-scratch
// implementation in another language would read and run the same file.
// ---------------------------------------------------------------------------

type readInputGen struct {
	RepeatB64 string `json:"repeat_b64"`
	Count     int    `json:"count"`
}

type readBundleOptions struct {
	Issuer string   `json:"issuer"`
	KeyIDs []string `json:"key_ids"`
	At     string   `json:"at"`
}

type readBundleExpect struct {
	Result        string         `json:"result"`
	Verification  map[string]any `json:"verification"`
	ArtifactMatch *bool          `json:"artifact_match"`
}

type readBundleCase struct {
	Name        string            `json:"name"`
	Reason      string            `json:"reason"`
	InputB64    *string           `json:"input_b64"`
	InputGen    *readInputGen     `json:"input_gen"`
	Options     readBundleOptions `json:"options"`
	ArtifactB64 *string           `json:"artifact_b64"`
	Expect      readBundleExpect  `json:"expect"`
}

type readStrictJSONCase struct {
	Name         string        `json:"name"`
	Reason       string        `json:"reason"`
	InputB64     *string       `json:"input_b64"`
	InputGen     *readInputGen `json:"input_gen"`
	Expect       string        `json:"expect"`
	CanonicalB64 *string       `json:"canonical_b64"`
}

type readIssuerCase struct {
	Value  string `json:"value"`
	Expect string `json:"expect"`
}

type readConformanceFile struct {
	Protocol        string               `json:"protocol"`
	Format          int                  `json:"format"`
	Notice          string               `json:"notice"`
	BundleCases     []readBundleCase     `json:"bundle_cases"`
	StrictJSONCases []readStrictJSONCase `json:"strict_json_cases"`
	IssuerCases     []readIssuerCase     `json:"issuer_cases"`
}

func readConformanceInput(t *testing.T, b64 *base64.Encoding, inputB64 *string, gen *readInputGen) []byte {
	t.Helper()
	switch {
	case inputB64 != nil && gen != nil:
		t.Fatal("case has both input_b64 and input_gen")
		return nil
	case inputB64 != nil:
		raw, err := b64.DecodeString(*inputB64)
		if err != nil {
			t.Fatalf("decoding input_b64: %v", err)
		}
		return raw
	case gen != nil:
		repeat, err := b64.DecodeString(gen.RepeatB64)
		if err != nil {
			t.Fatalf("decoding input_gen.repeat_b64: %v", err)
		}
		return bytes.Repeat(repeat, gen.Count)
	default:
		t.Fatal("case has neither input_b64 nor input_gen")
		return nil
	}
}

func TestConformanceCases(t *testing.T) {
	path := filepath.Join("..", "testdata", "apostille", "core-0.1-cases.json")
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var file readConformanceFile
	if err := json.Unmarshal(raw, &file); err != nil {
		t.Fatal(err)
	}

	if file.Protocol != Protocol || file.Format != 1 {
		t.Fatalf("unsupported case file: protocol %q format %d", file.Protocol, file.Format)
	}
	if len(file.BundleCases) == 0 {
		t.Fatal("no bundle_cases in file")
	}
	if len(file.StrictJSONCases) == 0 {
		t.Fatal("no strict_json_cases in file")
	}
	if len(file.IssuerCases) == 0 {
		t.Fatal("no issuer_cases in file")
	}
	seenNames := map[string]bool{}
	for _, c := range file.BundleCases {
		if seenNames[c.Name] {
			t.Fatalf("duplicate bundle case name: %s", c.Name)
		}
		seenNames[c.Name] = true
	}
	seenStrictNames := map[string]bool{}
	for _, c := range file.StrictJSONCases {
		if seenStrictNames[c.Name] {
			t.Fatalf("duplicate strict_json case name: %s", c.Name)
		}
		seenStrictNames[c.Name] = true
	}

	b64 := base64.RawURLEncoding.Strict()

	t.Run("bundle", func(t *testing.T) {
		for _, c := range file.BundleCases {
			t.Run(c.Name, func(t *testing.T) {
				raw := readConformanceInput(t, b64, c.InputB64, c.InputGen)
				opts := VerifyOptions{ExpectedIssuer: c.Options.Issuer, TrustedKeyIDs: c.Options.KeyIDs}
				if c.Options.At != "" {
					at, err := Timestamp(c.Options.At)
					if err != nil {
						t.Fatalf("unparsable options.at %q: %v", c.Options.At, err)
					}
					opts.Now = at
				}
				v, err := Verify(raw, opts)
				switch c.Expect.Result {
				case "reject":
					if err == nil {
						t.Fatal("expected reject, got accept")
					}
				case "accept":
					if err != nil {
						t.Fatalf("expected accept, got error: %v", err)
					}
					vRaw, mErr := json.Marshal(v)
					if mErr != nil {
						t.Fatal(mErr)
					}
					var vMap map[string]any
					if err := json.Unmarshal(vRaw, &vMap); err != nil {
						t.Fatal(err)
					}
					for key, want := range c.Expect.Verification {
						if key == "statement" {
							continue
						}
						got, ok := vMap[key]
						if !ok {
							t.Fatalf("verification result missing key %q", key)
						}
						if got != want {
							t.Fatalf("verification[%s] = %v, want %v", key, got, want)
						}
					}
					if c.ArtifactB64 != nil {
						artifact, err := b64.DecodeString(*c.ArtifactB64)
						if err != nil {
							t.Fatalf("decoding artifact_b64: %v", err)
						}
						if c.Expect.ArtifactMatch == nil {
							t.Fatal("artifact_b64 without expect.artifact_match")
						}
						if got := VerifyArtifact(v, artifact); got != *c.Expect.ArtifactMatch {
							t.Fatalf("VerifyArtifact = %v, want %v", got, *c.Expect.ArtifactMatch)
						}
					}
				default:
					t.Fatalf("unknown expect.result %q", c.Expect.Result)
				}
			})
		}
	})

	t.Run("strict_json", func(t *testing.T) {
		for _, c := range file.StrictJSONCases {
			t.Run(c.Name, func(t *testing.T) {
				raw := readConformanceInput(t, b64, c.InputB64, c.InputGen)
				var dst any
				err := StrictJSON(raw, &dst)
				switch c.Expect {
				case "reject":
					if err == nil {
						t.Fatal("expected reject, got accept")
					}
				case "accept":
					if err != nil {
						t.Fatalf("expected accept, got error: %v", err)
					}
					if c.CanonicalB64 == nil {
						t.Fatal("accept case missing canonical_b64")
					}
					canonical, err := Canonical(dst)
					if err != nil {
						t.Fatal(err)
					}
					wantCanonical, err := b64.DecodeString(*c.CanonicalB64)
					if err != nil {
						t.Fatalf("decoding canonical_b64: %v", err)
					}
					if !bytes.Equal(canonical, wantCanonical) {
						t.Fatalf("canonical = %s, want %s", canonical, wantCanonical)
					}
				default:
					t.Fatalf("unknown expect %q", c.Expect)
				}
			})
		}
	})

	t.Run("issuer", func(t *testing.T) {
		for _, c := range file.IssuerCases {
			t.Run(c.Value, func(t *testing.T) {
				want := c.Expect == "accept"
				if got := ValidIssuer(c.Value); got != want {
					t.Fatalf("ValidIssuer(%q) = %v, want %v", c.Value, got, want)
				}
			})
		}
	})
}
